def version_callback(value: bool):
    if value:
        print(f"ici {__version__}")
        raise typer.Exit()

def main_callback(
    ctx: typer.Context,
    version: bool | None = typer.Option(
        None,
        "--version",
        "-v",
        callback=version_callback,
        is_eager=True,
        help="Show version and exit",
    ),
):
    if not version:
        ctx.ensure_object(dict)
        try:
            ctx.obj["config"] = load_config()
        except ConfigError as err:
            typer.echo(f"Configuration error: {err}", err=True)
            raise typer.Exit(code=2) from err

def cmd_doctor(
    ctx: typer.Context,
    brief: bool = typer.Option(
        False, "--brief", help="Concise single-screen brief for closed-network survey"
    ),
    as_json: bool = typer.Option(False, "--json", help="Output machine-readable JSON"),
):
    """Diagnoses toolchains, Python candidates, compilers, and shared paths."""
    data = collect_diagnostics(Path.cwd().resolve(), _effective_config(ctx))
    if as_json:
        print(json.dumps(data, indent=2, ensure_ascii=False))
    elif brief:
        render_doctor_brief(data)
    else:
        render_doctor_table(data)

def cmd_env(
    csh: bool = typer.Option(False, "--csh", help="Generate tcsh / csh environment loader syntax"),
    sh: bool = typer.Option(
        False, "--sh", help="Generate bash / zsh / sh environment loader syntax"
    ),
):
    """Generates shell environment setup lines to paste into .cshrc or .bashrc."""
    local_bin = str(Path.home() / ".local/bin")
    if csh:
        print(f'setenv PATH "{local_bin}:$PATH"')
    else:
        print(f'export PATH="{local_bin}:$PATH"')

def _effective_config(ctx: typer.Context):
    """Return the effective policy loaded by the CLI callback."""

    obj = ctx.ensure_object(dict)
    config = obj.get("config")
    if isinstance(config, dict):
        return config
    return load_config(Path.cwd().resolve())

def _create_engine(engine_cls, config=None):
    """Construct an engine with the effective policy for the current project."""

    root = Path.cwd().resolve()
    return engine_cls(root, config if config is not None else load_config(root))

def _exit_for_safety_status(status: EngineStatus) -> None:
    code = exit_code_for_status(status)
    if code:
        raise typer.Exit(code=code)

def _save_single_report(filename: str, res: EngineResult) -> None:
    save_engine_json_report(res, Path(filename))
    console.print(f"[dim]Report saved to: {filename}[/dim]")

def _print_engine_result(res: EngineResult) -> None:
    """Render one engine result with a status-aware icon and escaped summary."""
    style, icon = {
        EngineStatus.PASS: ("bold green", "✔"),
        EngineStatus.WARN: ("bold yellow", "⚠"),
        EngineStatus.FAIL: ("bold red", "✘"),
        EngineStatus.ERROR: ("bold red", "✘"),
        EngineStatus.SKIP: ("dim", "↷"),
    }[res.status]
    console.print(f"[{style}]{icon}[/] {escape(res.summary)}")

def _open_in_browser(html_path: str) -> None:
    path_obj = Path(html_path).resolve()
    for opener in ("wslview", "xdg-open", "open"):
        if shutil.which(opener):
            subprocess.run([opener, str(path_obj)], capture_output=True)
            return

def _make_handler(_cls_name=_cls, _report_filename=_filename, _doc=_doc):
        def handler(
            ctx: typer.Context,
            report: bool = typer.Option(False, "--report", "-r", help="Save JSON report"),
        ):
            _run_engine_command(_cls_name, _report_filename, ctx, report)

        handler.__doc__ = _doc
        return handler

def handler(
            ctx: typer.Context,
            report: bool = typer.Option(False, "--report", "-r", help="Save JSON report"),
        ):
            _run_engine_command(_cls_name, _report_filename, ctx, report)

def load_config(base_dir: Path | None = None) -> dict[str, Any]:
    """Load the effective policy in deterministic precedence order.

    Defaults are merged first, followed by the XDG global policy, the
    project's ``ici.toml`` and ``dev.toml``, and finally ``ICI_CONFIG`` when
    set.  Every present file is loaded; malformed files and a missing
    explicitly requested file are configuration errors.
    """
    import copy

    config = copy.deepcopy(DEFAULT_CONFIG)
    base = _resolve_filesystem_path(base_dir or Path.cwd(), "project root")
    explicit_value = os.environ.get("ICI_CONFIG")
    explicit_path = (
        _resolve_filesystem_path(Path(explicit_value).expanduser(), "explicit configuration")
        if explicit_value
        else None
    )

    loaded = False
    for path in _config_paths(base, explicit_path):
        try:
            exists = path.exists()
        except OSError as err:
            raise ConfigError(f"could not inspect configuration {path}: {err}") from err
        if not exists:
            if explicit_path is not None and path == explicit_path:
                raise ConfigError(f"explicit configuration file does not exist: {path}")
            continue
        try:
            is_file = path.is_file()
        except OSError as err:
            raise ConfigError(f"could not inspect configuration {path}: {err}") from err
        if not is_file:
            raise ConfigError(f"configuration path is not a file: {path}")
        try:
            with path.open("rb") as stream:
                try:
                    user_cfg = tomli.load(stream)
                except (ValueError, RecursionError) as err:
                    raise ConfigError(f"could not parse configuration {path}: {err}") from err
        except OSError as err:
            raise ConfigError(f"could not read configuration {path}: {err}") from err
        if not isinstance(user_cfg, dict):
            raise ConfigError(f"configuration must be a table: {path}")
        _deep_merge(config, user_cfg)
        loaded = True

    if not loaded and explicit_path is None:
        _ensure_global_default_config(config)

    validate_config(config)
    validate_config_paths(config, base)
    return config

def _resolve_filesystem_path(path: Path, description: str) -> Path:
    """Canonicalize a filesystem path and normalize resolution failures."""

    try:
        return path.resolve(strict=False)
    except (OSError, RuntimeError, TypeError, ValueError) as err:
        raise ConfigError(f"could not resolve {description} path {path}: {err}") from err

def _config_paths(base: Path, explicit_path: Path | None = None) -> list[Path]:
    """Return policy files in their fixed precedence order."""

    paths = [
        _resolve_filesystem_path(get_global_config_path(), "global configuration"),
        _resolve_filesystem_path(base / "ici.toml", "project configuration"),
        _resolve_filesystem_path(base / "dev.toml", "development configuration"),
    ]
    if explicit_path is None:
        explicit = os.environ.get("ICI_CONFIG")
        if explicit:
            explicit_path = _resolve_filesystem_path(
                Path(explicit).expanduser(), "explicit configuration"
            )
    if explicit_path is not None:
        paths.append(explicit_path)
    return paths

def _ensure_global_default_config(config: dict[str, Any]) -> None:
    """Creates the per-user global ici.toml from the default policy on first run."""
    target = get_global_config_path()
    try:
        if target.exists():
            return
        target.parent.mkdir(parents=True, exist_ok=True)
        save_config(config, target)
        print(f"[ici] 기본 전역 설정을 생성했습니다: {target}", file=sys.stderr)
    except RuntimeError as err:
        raise ConfigError(f"could not resolve global configuration path {target}: {err}") from err
    except OSError as err:
        _ = err

def get_engine_config(config: dict[str, Any], engine_name: str) -> dict[str, Any]:
    """Extracts specific engine configuration dictionary."""
    engines = config.get("engines", {})
    return engines.get(engine_name, {})

def _deep_merge(base: dict[str, Any], override: dict[str, Any]) -> None:
    for k, v in override.items():
        if k in base and isinstance(base[k], dict) and isinstance(v, dict):
            _deep_merge(base[k], v)
        else:
            base[k] = v

def resolve_project_path(base: Path, value: str) -> Path:
    """Resolve a project-relative setting and require it to stay in ``base``."""

    from ici.core.path_utils import resolve_project_path as _core_resolve

    try:
        return _core_resolve(base, value)
    except ValueError as err:
        raise ConfigError(str(err)) from err

def _reject_unknown(table: dict[str, Any], allowed: set[str] | frozenset[str], path: str) -> None:
    for key in table:
        if key not in allowed:
            raise _error(f"{path}.{key}" if path else str(key), "is an unknown configuration key")

def _require_bool(value: Any, path: str) -> None:
    if not isinstance(value, bool):
        raise _error(path, "must be a boolean")

def _require_string(value: Any, path: str, *, non_empty: bool = False) -> None:
    if not isinstance(value, str) or (non_empty and not value.strip()):
        suffix = " non-empty" if non_empty else ""
        raise _error(path, f"must be a{suffix} string")

def _require_int(value: Any, path: str, *, minimum: int | None = None) -> None:
    if not isinstance(value, int) or isinstance(value, bool):
        raise _error(path, "must be an integer")
    if minimum is not None and value < minimum:
        raise _error(path, f"must be greater than or equal to {minimum}")

def _require_number(
    value: Any,
    path: str,
    *,
    minimum: float | None = None,
    maximum: float | None = None,
) -> None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise _error(path, "must be a number")
    try:
        numeric_value = float(value)
    except (OverflowError, TypeError, ValueError) as err:
        raise _error(path, "must be a finite number") from err
    if not math.isfinite(numeric_value):
        raise _error(path, "must be finite")
    if minimum is not None and numeric_value < minimum:
        raise _error(path, f"must be greater than or equal to {minimum:g}")
    if maximum is not None and numeric_value > maximum:
        raise _error(path, f"must be less than or equal to {maximum:g}")

def _require_string_list(value: Any, path: str) -> None:
    if not isinstance(value, list) or any(not isinstance(item, str) or not item for item in value):
        raise _error(path, "must be a list of non-empty strings")

def _validate_mode(table: dict[str, Any], path: str) -> None:
    if "mode" not in table:
        return
    mode = table["mode"]
    _require_string(mode, f"{path}.mode", non_empty=True)
    if mode not in MODES:
        allowed = ", ".join(sorted(MODES))
        raise _error(f"{path}.mode", f"must be one of: {allowed}")

def _validate_common_engine(table: dict[str, Any], path: str) -> None:
    if "enabled" in table:
        _require_bool(table["enabled"], f"{path}.enabled")
    if "required" in table:
        _require_bool(table["required"], f"{path}.required")
    _validate_mode(table, path)

def _validate_line(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    if "warn_limit" in table:
        _require_int(table["warn_limit"], f"{path}.warn_limit", minimum=1)
    if "fail_limit" in table:
        _require_int(table["fail_limit"], f"{path}.fail_limit", minimum=1)
    if "gate_dirs" in table:
        _require_string_list(table["gate_dirs"], f"{path}.gate_dirs")
    if "include_dirs" in table:
        _require_string_list(table["include_dirs"], f"{path}.include_dirs")
    if "exclude_dirs" in table:
        _require_string_list(table["exclude_dirs"], f"{path}.exclude_dirs")

    warn_limit = table.get("warn_limit", 500)
    fail_limit = table.get("fail_limit", 1000)
    if fail_limit < warn_limit:
        raise _error(
            f"{path}.warn_limit",
            "must be less than or equal to engines.line.fail_limit",
        )

def _validate_test(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    if "coverage_required" in table:
        _require_bool(table["coverage_required"], f"{path}.coverage_required")
    if "python" in table:
        _require_string(table["python"], f"{path}.python", non_empty=True)
    if "min_tem_score" in table:
        _require_number(table["min_tem_score"], f"{path}.min_tem_score", minimum=0, maximum=5)
    if "min_branch_cov" in table:
        _require_number(table["min_branch_cov"], f"{path}.min_branch_cov", minimum=0, maximum=100)
    if "min_func_cov" in table:
        _require_number(table["min_func_cov"], f"{path}.min_func_cov", minimum=0, maximum=100)

def _validate_type(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    for key in ("fail_on_error", "warn_on_missing_annotation", "mypy_required"):
        if key in table:
            _require_bool(table[key], f"{path}.{key}")

def _validate_lint(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    if "ruff_required" in table:
        _require_bool(table["ruff_required"], f"{path}.ruff_required")

def _validate_complexity(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    for key in ("warn_cc", "fail_cc", "warn_nesting"):
        if key in table:
            _require_int(table[key], f"{path}.{key}", minimum=1)
    warn_cc = table.get("warn_cc", 15)
    fail_cc = table.get("fail_cc", 25)
    if fail_cc < warn_cc:
        raise _error(f"{path}.warn_cc", "must be less than or equal to engines.complexity.fail_cc")

def _validate_dup(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    for key in ("warn_pct", "fail_pct"):
        if key in table:
            _require_number(table[key], f"{path}.{key}", minimum=0, maximum=100)
    if "min_window" in table:
        _require_int(table["min_window"], f"{path}.min_window", minimum=1)
    warn_pct = table.get("warn_pct", 5.0)
    fail_pct = table.get("fail_pct", 15.0)
    if fail_pct < warn_pct:
        raise _error(f"{path}.warn_pct", "must be less than or equal to engines.dup.fail_pct")

def _validate_build(table: Any) -> None:
    path = "build"
    if not isinstance(table, dict):
        raise _error(path, "must be a table")
    _reject_unknown(table, _BUILD_KEYS, path)
    if "python" not in table:
        return
    python = table["python"]
    if not isinstance(python, dict):
        raise _error("build.python", "must be a table")
    _reject_unknown(python, _BUILD_PYTHON_KEYS, "build.python")
    if "entrypoint" in python:
        _require_string(python["entrypoint"], "build.python.entrypoint", non_empty=True)

def _validate_doctor(table: Any) -> None:
    path = "doctor"
    if not isinstance(table, dict):
        raise _error(path, "must be a table")
    _reject_unknown(table, _DOCTOR_KEYS, path)
    if "required_tools" in table:
        _require_string_list(table["required_tools"], f"{path}.required_tools")

def _validate_security(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    if "scan_tests" in table:
        _require_bool(table["scan_tests"], f"{path}.scan_tests")

def _validate_cognitive(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    for key in ("warn", "fail", "warn_nesting"):
        if key in table:
            _require_int(table[key], f"{path}.{key}", minimum=1)
    # Matches CognitiveEngine's own fallback and DEFAULT_CONFIG's shipped
    # policy (warn=30, fail=60) — kept in sync deliberately.
    w = table.get("warn", 30)
    f = table.get("fail", 60)
    if f < w:
        raise _error(f"{path}.warn", "must be <= fail")

def _validate_cycle(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    if "max_reported" in table:
        _require_int(table["max_reported"], f"{path}.max_reported", minimum=1)

def _validate_metadata(table: Any, path: str) -> None:
    if not isinstance(table, dict):
        raise _error(path, "must be a table")
    allowed = _ICI_KEYS if path == "ici" else _PROJECT_KEYS
    _reject_unknown(table, allowed, path)
    for key, value in table.items():
        if path == "project" and key == "source_dirs":
            _require_string_list(value, "project.source_dirs")
        elif key == "type":
            _require_string(value, f"{path}.{key}", non_empty=True)
            if value not in PROJECT_TYPES:
                raise _error(f"{path}.{key}", "must be one of: cpp, hybrid, python")
        else:
            _require_string(value, f"{path}.{key}", non_empty=True)

def _validate_path_list(value: Any, setting: str, base: Path) -> None:
    """Validate and canonicalize a list of project-relative path settings."""

    if not isinstance(value, list):
        raise _error(setting, "must be a list of non-empty strings")
    for index, item in enumerate(value):
        item_path = f"{setting}[{index}]"
        if not isinstance(item, str) or not item:
            raise _error(item_path, "must be a non-empty string")
        try:
            resolve_project_path(base, item)
        except ConfigError as err:
            raise ConfigError(f"{item_path}: {err}") from err

def validate_config_paths(config: dict[str, Any], base: Path) -> None:
    """Reject configured paths that resolve outside the project root.

    This function deliberately accepts partial engine configurations so
    standalone engine construction remains safe even when tests or callers
    provide only the relevant engine table instead of a fully merged policy.
    """

    if not isinstance(config, dict):
        raise ConfigError("configuration must be a table")

    project = config.get("project")
    if isinstance(project, dict) and "source_dirs" in project:
        _validate_path_list(project["source_dirs"], "project.source_dirs", base)

    engines = config.get("engines")
    if not isinstance(engines, dict):
        return
    line = engines.get("line")
    if not isinstance(line, dict):
        return
    for key in ("gate_dirs", "include_dirs", "exclude_dirs"):
        if key in line:
            _validate_path_list(line[key], f"engines.line.{key}", base)

def validate_config(config: dict[str, Any]) -> None:
    """Validate an effective configuration and raise :class:`ConfigError` on failure."""

    if not isinstance(config, dict):
        raise ConfigError("configuration must be a table")
    _reject_unknown(config, _TOP_LEVEL_KEYS, "")

    for key in ("ici", "project"):
        if key in config:
            _validate_metadata(config[key], key)
    for key in ("name", "version"):
        if key in config:
            _require_string(config[key], key, non_empty=True)
    if "type" in config:
        _require_string(config["type"], "type", non_empty=True)
        if config["type"] not in PROJECT_TYPES:
            raise _error("type", "must be one of: cpp, hybrid, python")

    if "build" in config:
        _validate_build(config["build"])

    if "doctor" in config:
        _validate_doctor(config["doctor"])

    engines = config.get("engines")
    if not isinstance(engines, dict):
        raise ConfigError("engines must be a table")
    _reject_unknown(engines, frozenset(_ENGINE_KEYS), "engines")
    for name, table in engines.items():
        _validate_engine(name, table)

def find_infra_root(start_dir: Path | None = None) -> Path:
    """Finds the root of the infrastructure repository or workspace."""
    if "ICI_INFRA_ROOT" in os.environ:
        return Path(os.environ["ICI_INFRA_ROOT"]).resolve()
    if "DEVOPS_INFRA_ROOT" in os.environ:
        return Path(os.environ["DEVOPS_INFRA_ROOT"]).resolve()

    curr = (start_dir or Path.cwd()).resolve()
    for parent in [curr, *list(curr.parents)]:
        if (parent / "nas_shared").exists():
            return parent
        if (parent / ".git").exists() and (parent / "ici").exists():
            return parent

    return curr

def get_nas_shared_dir() -> Path:
    """Returns the nas_shared directory path."""
    if "NAS_SHARED_DIR" in os.environ:
        return Path(os.environ["NAS_SHARED_DIR"]).resolve()
    infra_root = find_infra_root()
    return infra_root / "nas_shared"

def find_uv() -> str | None:
    """Locates the uv executable: $ICI_UV, shared NAS/infra paths, then PATH."""
    ici_uv = os.environ.get("ICI_UV")
    if ici_uv and os.path.isfile(ici_uv) and os.access(ici_uv, os.X_OK):
        return ici_uv

    candidates = [
        Path.home() / ".local" / "bin" / "uv",
        get_nas_shared_dir() / "bin" / "uv",
        find_infra_root() / "bin" / "uv",
    ]
    for cand in candidates:
        if cand.is_file() and os.access(str(cand), os.X_OK):
            return str(cand)

    return shutil.which("uv")

def find_project_executable(project_root: Path, name: str) -> str | None:
    """Find a directly executable tool in the project's virtual environment.

    Package runners such as ``uv run`` and ``uvx`` are intentionally excluded:
    resolving a missing tool through them can access the network or mutate the
    environment.  The explicit candidates cover the Unix and Windows venv
    layouts while requiring executable permissions on Unix.
    """

    for directory in ("bin", "Scripts"):
        for suffix in ("", ".exe"):
            candidate = project_root / ".venv" / directory / f"{name}{suffix}"
            if not candidate.is_file():
                continue
            if os.name == "nt" or os.access(str(candidate), os.X_OK):
                return str(candidate)
    return None

def get_nas_cpp_lib_dir() -> Path:
    """Returns the default NAS shared C++ library directory."""
    return get_nas_shared_dir() / "libs/cpp/ips-core-lib/v1.2.3/x86_64"

def get_glibc_version() -> str:
    """Detects the system glibc version."""
    try:
        res = subprocess.run(["ldd", "--version"], capture_output=True, text=True, timeout=2)
        if res.stdout:
            first_line = res.stdout.splitlines()[0]
            # e.g., "ldd (GNU libc) 2.28" or "ldd (Ubuntu GLIBC 2.35-0ubuntu3.8) 2.35"
            parts = first_line.split()
            for part in reversed(parts):
                if part.replace(".", "").isdigit():
                    return part
    except (OSError, subprocess.SubprocessError) as err:
        _ = err
    try:
        import ctypes

        gnu_get_libc_version = ctypes.CDLL(None).gnu_get_libc_version
        gnu_get_libc_version.restype = ctypes.c_char_p
        return gnu_get_libc_version().decode("utf-8")
    except (OSError, AttributeError) as err:
        _ = err
        return "unknown"

def is_wsl() -> bool:
    """Checks if running inside Windows Subsystem for Linux."""
    if "WSL_DISTRO_NAME" in os.environ or "WSL_INTEROP" in os.environ:
        return True
    try:
        with open("/proc/version", encoding="utf-8") as f:
            content = f.read().lower()
            return "microsoft" in content or "wsl" in content
    except OSError as err:
        _ = err
        return False

def get_os_release_info() -> dict[str, str]:
    """Reads /etc/os-release into a dictionary."""
    info = {}
    os_release = Path("/etc/os-release")
    if os_release.exists():
        try:
            with open(os_release, encoding="utf-8") as f:
                for line in f:
                    if "=" in line and not line.startswith("#"):
                        k, v = line.strip().split("=", 1)
                        info[k] = v.strip('"').strip("'")
        except OSError as err:
            _ = err
    return info

def find_python_candidates() -> list[tuple[str, str, str]]:
    """Finds all candidate Python interpreters and their detected versions.

    Returns list of tuples: (candidate_name, path, version_str)
    """
    results = []
    seen_paths = set()

    # 1. Custom ICI_PYTHON
    if os.environ.get("ICI_PYTHON"):
        p = shutil.which(os.environ["ICI_PYTHON"]) or os.environ["ICI_PYTHON"]
        if os.path.exists(p) and os.access(p, os.X_OK):
            ver = _get_py_ver(p)
            if ver:
                results.append(("$ICI_PYTHON", p, ver))
                seen_paths.add(os.path.realpath(p))

    # 2. Standard Candidates
    for cand in PYTHON_CANDIDATES:
        cand_p = shutil.which(cand)
        if cand_p and os.access(cand_p, os.X_OK):
            real = os.path.realpath(cand_p)
            if real not in seen_paths:
                ver = _get_py_ver(cand_p)
                if ver:
                    results.append((cand, cand_p, ver))
                    seen_paths.add(real)

    return results

def _get_py_ver(py_path: str) -> str | None:
    try:
        res = subprocess.run(
            [
                py_path,
                "-c",
                "import sys; print(f'{sys.version_info[0]}.{sys.version_info[1]}.{sys.version_info[2]}')",
            ],
            capture_output=True,
            text=True,
            timeout=2,
        )
        if res.returncode == 0:
            return res.stdout.strip()
    except (OSError, subprocess.SubprocessError) as err:
        _ = err
    return None

def aggregate_suite_status(results: list[EngineResult]) -> EngineStatus:
    """Aggregates engine results into the suite gate status."""
    if not results:
        return EngineStatus.ERROR
    if any(
        r.required
        and (
            r.status in (EngineStatus.ERROR, EngineStatus.SKIP)
            or r.evidence == EvidenceState.NOT_RUN
        )
        for r in results
    ):
        return EngineStatus.ERROR
    if any(r.required and r.status == EngineStatus.FAIL for r in results):
        return EngineStatus.FAIL
    if any(
        r.status == EngineStatus.WARN
        or (
            not r.required
            and (r.status != EngineStatus.PASS or r.evidence != EvidenceState.MEASURED)
        )
        for r in results
    ):
        return EngineStatus.WARN
    return EngineStatus.PASS

def format_score_display(res: EngineResult) -> str:
    """Formats formatted score string or metrics summary."""
    if res.score is not None:
        if res.max_score is not None:
            return f"{res.score:.2f} / {res.max_score:.2f}"
        return f"{res.score:.2f}"
    if "metrics_summary" in res.extra:
        return str(res.extra["metrics_summary"])
    return "-"

def exit_code_for_status(status: EngineStatus) -> int:
    """Maps a result status to the stable command-line exit contract."""
    if status in (EngineStatus.FAIL, EngineStatus.ERROR):
        return 1
    if status == EngineStatus.SKIP:
        return 2
    return 0

def failed_count(self) -> int:
        """Return legacy FAIL+ERROR count for backward-compatible consumers."""
        return sum(1 for r in self.results if r.status in (EngineStatus.FAIL, EngineStatus.ERROR))

def error_count(self) -> int:
        """Returns the number of engines that could not produce a result."""
        return sum(1 for r in self.results if r.status == EngineStatus.ERROR)

def skipped_count(self) -> int:
        """Returns the number of engines that were intentionally not run."""
        return sum(1 for r in self.results if r.status == EngineStatus.SKIP)

def _resolve_project_root(base: Path) -> Path:
    try:
        return Path(base).resolve(strict=False)
    except (OSError, RuntimeError, TypeError, ValueError) as err:
        raise ValueError(f"could not resolve project root {base}: {err}") from err

def resolve_project_path(base: Path, value: str) -> Path:
    """Resolve a project-relative path and enforce canonical containment.

    Raises ValueError if the resolved path escapes the project root.
    """
    try:
        project_root = _resolve_project_root(Path(base))
        candidate = (project_root / value).resolve(strict=False)
    except (OSError, RuntimeError, TypeError, ValueError) as err:
        raise ValueError(f"could not resolve project path {value!r}: {err}") from err

    try:
        candidate.relative_to(project_root)
    except ValueError as err:
        raise ValueError(f"path is outside project root: {value}") from err
    return candidate

def _safe_project_file(base: Path, name: str) -> Path | None:
    """Return an existing in-project file without following an escaped link."""
    try:
        candidate = resolve_project_path(base, name)
        return candidate if candidate.is_file() else None
    except (OSError, ValueError):
        return None

def _safe_project_dir(base: Path, path: Path) -> Path | None:
    """Return an existing in-project directory without following an escaped link."""
    try:
        candidate = resolve_project_path(base, os.fspath(path))
        return candidate if candidate.is_dir() else None
    except (OSError, ValueError):
        return None

def _iter_project_files(root: Path, base: Path, suffixes: tuple[str, ...]) -> Iterator[Path]:
    """Yield contained regular files while ignoring symlink traversal."""
    safe_root = _safe_project_dir(base, root)
    if safe_root is None:
        return

    for current, dir_names, file_names in os.walk(safe_root, topdown=True, followlinks=False):
        current_path = Path(current)
        safe_names: list[str] = []
        for dir_name in dir_names:
            path = current_path / dir_name
            if path.is_symlink():
                continue
            safe_dir = _safe_project_dir(base, path)
            if safe_dir is None or _should_ignore_path(safe_dir):
                continue
            safe_names.append(dir_name)
        dir_names[:] = safe_names

        for file_name in file_names:
            path = current_path / file_name
            if path.is_symlink() or path.suffix not in suffixes:
                continue
            try:
                canonical = resolve_project_path(base, os.fspath(path))
                if canonical.is_file() and not _should_ignore_path(canonical):
                    yield canonical
            except (OSError, ValueError):
                continue

def get_source_dirs(
    base_path: Path | None = None, config: dict[str, Any] | None = None
) -> list[Path]:
    """Resolves existing project source directories (overridable via config project.source_dirs)."""
    base = _resolve_project_root(base_path or Path.cwd())
    names: list[str] | None = None
    configured = False
    if config:
        proj_cfg = config.get("project")
        if isinstance(proj_cfg, dict):
            raw = proj_cfg.get("source_dirs")
            if isinstance(raw, list):
                configured = True
                names = []
                for item in raw:
                    if not isinstance(item, str) or not item:
                        raise ValueError("project.source_dirs must be a list of non-empty strings")
                    names.append(item)
    if names is None:
        names = DEFAULT_SOURCE_DIRS

    dirs: list[Path] = []
    for name in names:
        try:
            candidate = resolve_project_path(base, name)
        except ValueError:
            if configured:
                raise
            continue
        try:
            if candidate.is_dir():
                dirs.append(candidate)
        except OSError as err:
            if configured:
                raise ValueError(f"could not inspect source directory {name!r}: {err}") from err
    return dirs

def detect_project_type(target_dir: Path | None = None) -> str:
    """Detects whether target project is 'cpp', 'python', or 'hybrid'."""
    base = _resolve_project_root(target_dir or Path.cwd())

    # 1. Check configuration files (ici.toml, dev.toml)
    for conf_name in ("ici.toml", "dev.toml"):
        conf_path = _safe_project_file(base, conf_name)
        if conf_path is not None:
            try:
                content = conf_path.read_text(encoding="utf-8")
                if re.search(r'type\s*=\s*["\']hybrid["\']', content):
                    return "hybrid"
                elif re.search(r'type\s*=\s*["\']cpp["\']', content):
                    return "cpp"
                elif re.search(r'type\s*=\s*["\']python["\']', content):
                    return "python"
            except OSError as err:
                _ = err

    # 2. Check source file signatures across all configured source directories
    source_dirs = get_source_dirs(base)
    has_cpp = (
        _safe_project_file(base, "CMakeLists.txt") is not None
        or _safe_project_file(base, "Makefile") is not None
        or any(any(_iter_project_files(d, base, (".cpp",))) for d in source_dirs)
    )
    has_py = (
        _safe_project_file(base, "pyproject.toml") is not None
        or _safe_project_file(base, "setup.py") is not None
        or any(any(_iter_project_files(d, base, (".py",))) for d in source_dirs)
    )

    if has_cpp and has_py:
        return "hybrid"
    if has_cpp:
        return "cpp"
    return "python"

def _validate_project_name(value: Any) -> str:
    if (
        not isinstance(value, str)
        or value in {".", ".."}
        or _PROJECT_VALUE_PATTERN.fullmatch(value) is None
    ):
        raise ValueError(f"invalid project name: {value!r}")
    return value

def _validate_project_version(value: Any) -> str:
    if not isinstance(value, str):
        raise ValueError(f"invalid project version: {value!r}")
    normalized = value[1:] if value.startswith("v") else value
    if _PROJECT_VALUE_PATTERN.fullmatch(normalized) is None:
        raise ValueError(f"invalid project version: {value!r}")
    return f"v{normalized}"

def _metadata_path(base: Path, name: str) -> Path | None:
    """Resolve one project metadata file, rejecting an escaped symlink."""
    candidate = resolve_project_path(base, name)
    try:
        if not candidate.exists():
            return None
        if not candidate.is_file():
            raise ValueError(f"project metadata path is not a file: {name}")
    except OSError as err:
        raise ValueError(f"could not inspect project metadata {name}: {err}") from err
    return candidate

def _read_toml(path: Path) -> dict[str, Any]:
    """Read one canonical TOML metadata file."""
    try:
        with path.open("rb") as stream:
            try:
                document = tomli.load(stream)
            except (ValueError, RecursionError, UnicodeError) as err:
                raise ValueError(f"could not parse project metadata {path.name}: {err}") from err
    except OSError as err:
        raise ValueError(f"could not read project metadata {path.name}: {err}") from err
    if not isinstance(document, dict):
        raise ValueError(f"project metadata must be a table: {path.name}")
    return document

def _metadata_table(document: dict[str, Any], path_name: str) -> dict[str, Any]:
    if path_name == "pyproject.toml":
        project = document.get("project", {})
        if not isinstance(project, dict):
            raise ValueError("project metadata [project] must be a table")
        return project
    return document

def _git_project_version(base: Path) -> str:
    try:
        result = subprocess.run(
            ["git", "describe", "--tags", "--always"],
            capture_output=True,
            text=True,
            cwd=base,
            timeout=2,
        )
    except (OSError, subprocess.SubprocessError):
        return "v1.0.0"
    if result.returncode == 0 and result.stdout.strip():
        return _validate_project_version(result.stdout.strip())
    return "v1.0.0"

def read_project_metadata(base: Path) -> tuple[str, str]:
    """Read and validate project name/version from canonical TOML metadata."""
    project_root = _resolve_project_root(base)
    name: str | None = None
    version: str | None = None

    for file_name in ("ici.toml", "dev.toml", "pyproject.toml"):
        path = _metadata_path(project_root, file_name)
        if path is None:
            continue
        table = _metadata_table(_read_toml(path), file_name)
        if "name" in table:
            candidate_name = _validate_project_name(table["name"])
            if name is None:
                name = candidate_name
        if "version" in table:
            candidate_version = _validate_project_version(table["version"])
            if version is None:
                version = candidate_version

    if name is None:
        name = _validate_project_name(project_root.name)
    if version is None:
        version = _git_project_version(project_root)
    return name, version

def get_project_name(target_dir: Path | None = None) -> str:
    """Gets and validates the project name from TOML metadata or its directory."""
    return read_project_metadata(target_dir or Path.cwd())[0]

def get_project_version(target_dir: Path | None = None) -> str:
    """Extract and validate the project version or fall back to git/v1.0.0."""
    return read_project_metadata(target_dir or Path.cwd())[1]

def get_all_cpp_sources(
    base_path: Path | None = None, config: dict[str, Any] | None = None
) -> list[Path]:
    """Finds all C++ source files (.cpp, .cc, .cxx, .c) across project source directories."""
    base = _resolve_project_root(base_path or Path.cwd())
    cpp_files: list[Path] = []
    for src_dir in get_source_dirs(base, config):
        cpp_files.extend(_iter_project_files(src_dir, base, (".cpp", ".cc", ".cxx", ".c")))

    return sorted(cpp_files)

def get_all_cpp_includes(
    base_path: Path | None = None, config: dict[str, Any] | None = None
) -> list[str]:
    """Finds all C++ include directories (-I flags)."""
    base = _resolve_project_root(base_path or Path.cwd())
    inc_dirs = set()

    inc_dir = _safe_project_dir(base, base / "include")
    if inc_dir is not None:
        inc_dirs.add(f"-I{inc_dir}")
        for p in _iter_project_dirs(inc_dir, base):
            if not _should_ignore_path(p):
                inc_dirs.add(f"-I{p}")

    for src_dir in get_source_dirs(base, config):
        sub_inc = _safe_project_dir(base, src_dir / "include")
        if sub_inc is not None:
            inc_dirs.add(f"-I{sub_inc}")

    nas_cpp = get_nas_cpp_lib_dir()
    if nas_cpp.exists() and (nas_cpp / "include").exists():
        inc_dirs.add(f"-I{nas_cpp / 'include'}")

    return sorted(list(inc_dirs))

def get_all_python_sources(
    base_path: Path | None = None, config: dict[str, Any] | None = None
) -> list[Path]:
    """Finds all Python source files across project source directories."""
    base = _resolve_project_root(base_path or Path.cwd())
    py_files: list[Path] = []
    for src_dir in get_source_dirs(base, config):
        py_files.extend(_iter_project_files(src_dir, base, (".py",)))
    return sorted(py_files)

def _should_ignore_path(p: Path) -> bool:
    parts = p.parts
    return any(
        part in (".venv", "venv", "build", "__pycache__", ".git", ".pytest_cache", ".ruff_cache")
        or part.startswith("v1.")
        or part.startswith("v0.")
        for part in parts
    )

def _limit(text: str, maximum: int) -> tuple[str, bool]:
    """Limit captured output to ``maximum`` characters."""

    if len(text) <= maximum:
        return text, False
    return text[:maximum], True

def _decode_output(value: bytes | str | None) -> str:
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    return value or ""

def _drain_stream(stream, capture: _BoundedCapture) -> None:
    try:
        while True:
            chunk = stream.read(65536)
            if not chunk:
                return
            if isinstance(chunk, str):
                chunk = chunk.encode("utf-8", errors="replace")
            capture.append(chunk)
    except (OSError, ValueError):
        return
    finally:
        with suppress(OSError, ValueError):
            stream.close()

def _write_input(stream, input_bytes: bytes) -> None:
    try:
        stream.write(input_bytes)
        stream.close()
    except (BrokenPipeError, OSError, ValueError):
        return

def _start_input_writer(
    proc: subprocess.Popen[bytes], input_text: str | None
) -> threading.Thread | None:
    if input_text is None or proc.stdin is None:
        return None
    input_thread = threading.Thread(
        target=_write_input,
        args=(proc.stdin, input_text.encode("utf-8")),
        name="ici-process-stdin",
        daemon=True,
    )
    input_thread.start()
    return input_thread

def _close_windows_job(proc) -> None:
    job_handle = getattr(proc, "_ici_job_handle", None)
    kernel32 = getattr(proc, "_ici_job_kernel32", None)
    if job_handle and kernel32 is not None:
        with suppress(OSError):
            kernel32.CloseHandle(job_handle)
    for attr in ("_ici_job_handle", "_ici_job_kernel32"):
        with suppress(AttributeError):
            delattr(proc, attr)

def _wait_after_startup_failure(proc) -> None:
    try:
        proc.wait(timeout=1.0)
    except TypeError:
        try:
            proc.wait()
        except OSError as error:
            _log_cleanup_failure("waiting for startup failure", error)
    except (OSError, subprocess.TimeoutExpired) as error:
        _log_cleanup_failure("waiting for startup failure", error)

def _remaining(deadline: float | None) -> float | None:
    if deadline is None:
        return None
    return max(0.0, deadline - time.monotonic())

def _wait_process(proc, deadline: float | None = None) -> None:
    remaining = _remaining(deadline)
    if remaining is not None and remaining <= 0:
        return
    try:
        proc.wait(timeout=remaining) if remaining is not None else proc.wait()
    except TypeError:
        # Small fakes used by the platform orchestration tests expose wait()
        # without subprocess' optional timeout parameter.
        if remaining is None:
            with suppress(OSError):
                proc.wait()
    except (OSError, subprocess.TimeoutExpired):
        return

def _terminate_process(proc: subprocess.Popen[bytes], deadline: float | None = None) -> None:
    """Terminate a process and its POSIX process group when possible."""

    if os.name == "posix":
        try:
            os.killpg(proc.pid, signal.SIGTERM)
        except ProcessLookupError as error:
            _log_cleanup_failure("SIGTERM process-group cleanup", error)
        except OSError:
            proc.terminate()

        grace = _remaining(deadline)
        grace = 0.2 if grace is None else min(grace, 0.2)
        if grace > 0:
            with suppress(subprocess.TimeoutExpired):
                proc.wait(timeout=grace)

        # A child can exit on SIGTERM while descendants keep the pipe open.
        # Kill the group after the grace period so communicate() cannot hang.
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except ProcessLookupError as error:
            _log_cleanup_failure("SIGKILL process-group cleanup", error)
        except OSError:
            proc.kill()
    else:
        _terminate_windows_process(proc, deadline)

    _wait_process(proc, deadline)

def _wait_for_process(proc: subprocess.Popen[bytes], deadline: float | None) -> bool:
    try:
        proc.wait(timeout=_remaining(deadline))
    except subprocess.TimeoutExpired:
        _terminate_process(proc, deadline)
        return True
    return False

def _join_until_deadline(thread: threading.Thread, deadline: float | None) -> bool:
    thread.join(timeout=_remaining(deadline))
    return thread.is_alive()

def _close_stream(stream: IO[bytes] | None) -> None:
    if stream is not None:
        with suppress(OSError, ValueError):
            stream.close()

def _cleanup_failed_process(proc: subprocess.Popen[bytes] | None) -> None:
    if proc is None:
        return
    if os.name == "nt":
        _close_windows_job(proc)
    _close_process_pipes(proc)

def append(self, chunk: bytes) -> None:
        remaining = self._maximum - len(self._buffer)
        if remaining > 0:
            self._buffer.extend(chunk[:remaining])
        if len(chunk) > max(remaining, 0):
            self.truncated = True

def _process_handle(proc):
    process_handle = getattr(proc, "_handle", None)
    if process_handle is None:
        process_handle = getattr(proc, "handle", None)
    return process_handle

def _thread_handle(proc):
    thread_handle = getattr(proc, "_thread_handle", None)
    if thread_handle is None:
        thread_handle = getattr(proc, "_thread", None)
    return thread_handle

def _invalid_windows_handle(handle) -> bool:
    value = handle.value if isinstance(handle, ctypes.c_void_p) else handle
    return value in (None, 0, ctypes.c_void_p(-1).value)

def _first_meaningful_line(text: str) -> str:
    for line in text.splitlines():
        stripped = line.strip()
        if stripped:
            return stripped[:200]
    return ""

def collect_diagnostics(
    project_root: Path | None = None, config: dict[str, Any] | None = None
) -> dict[str, Any]:
    """Collects all environment and toolchain information."""
    sys_info = get_system_info()
    py_candidates = find_python_candidates()

    # Unified tool probing via core/toolchain (required_tools policy aware)
    if config is None:
        try:
            from ici.config import load_config

            config = load_config(project_root or Path.cwd())
        except Exception:
            config = {}
    required_tools = set(config.get("doctor", {}).get("required_tools", []) or [])
    probe_map: dict[str, list[str]] = dict(DEFAULT_PROBES)
    probe_map.update(
        {
            "clang": ["clang", "--version"],
            "clang-format": ["clang-format", "--version"],
            "ruff": ["ruff", "--version"],
            "mypy": ["mypy", "--version"],
            "pytest": ["pytest", "--version"],
            "uv": [find_uv() or "uv", "--version"],
        }
    )
    tools: dict[str, dict[str, Any]] = {}
    for tool_name, probe in probe_map.items():
        cap, _result = collect_tool_capability(tool_name, probe, cwd=project_root)
        tools[tool_name] = {
            "available": cap.available,
            "version": cap.version,
            "path": cap.path,
            "error": cap.error,
            "required": tool_name in required_tools,
        }

    # NAS checks
    nas_root = get_nas_shared_dir()
    nas_cpp = get_nas_cpp_lib_dir()
    infra_root = find_infra_root()

    return {
        "system": sys_info,
        "running_python": {
            "version": f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}",
            "executable": sys.executable,
        },
        "python_candidates": [
            {"candidate": c[0], "path": c[1], "version": c[2]} for c in py_candidates
        ],
        "tools": tools,
        "required_tools": sorted(required_tools),
        "paths": {
            "infra_root": str(infra_root),
            "nas_shared": str(nas_root),
            "nas_shared_exists": nas_root.exists(),
            "nas_cpp_lib": str(nas_cpp),
            "nas_cpp_lib_exists": nas_cpp.exists(),
        },
    }

def __init__(self, project_root: Path | None = None, config: dict[str, Any] | None = None):
        self.project_root = (project_root or Path.cwd()).resolve()
        self.config = config or {}
        validate_config_paths(self.config, self.project_root)

def run(self) -> EngineResult:
        """Executes the verification logic and returns a structured EngineResult."""
        pass

def get_config(self, engine_name: str) -> dict[str, Any]:
        """Gets configuration for this specific engine."""
        return get_engine_config(self.config, engine_name)

def evaluate_status(
        self, has_fail: bool, has_warn: bool, mode: str = "pass_warn_fail"
    ) -> EngineStatus:
        """Evaluates final engine status considering configured policy mode.

        mode options:
        - "pass_warn_fail" (default): FAIL on error, WARN on warning, else PASS
        - "pass_fail": FAIL on error or warning
        - "pass_warn": Downgrade all FAILs and WARNs to WARN (never fails CI)
        """
        if mode == "pass_fail":
            return EngineStatus.FAIL if (has_fail or has_warn) else EngineStatus.PASS
        elif mode == "pass_warn":
            return EngineStatus.WARN if (has_fail or has_warn) else EngineStatus.PASS
        else:  # pass_warn_fail
            if has_fail:
                return EngineStatus.FAIL
            elif has_warn:
                return EngineStatus.WARN
            return EngineStatus.PASS

def _blank_cpp_region(chars: list[str], start: int, end: int) -> None:
    for index in range(start, end):
        if chars[index] not in "\r\n":
            chars[index] = " "

def _cpp_line_comment_end(text: str, start: int) -> int:
    index = start + 2
    while index < len(text):
        if text[index] == "\n" and (index == start or text[index - 1] != "\\"):
            return index
        index += 1
    return len(text)

def _cpp_quoted_end(text: str, start: int) -> int:
    quote = text[start]
    index = start + 1
    while index < len(text):
        if text[index] == "\\":
            index += 2
            continue
        if text[index] == quote:
            return index + 1
        if text[index] in "\r\n":
            return index + 1
        index += 1
    return len(text)

def _mask_cpp_literals(text: str) -> str:
    """Blank comments and quoted C++ literals while preserving source lines."""

    chars = list(text)
    index = 0
    while index < len(text):
        raw_start = _CPP_RAW_START_RE.match(text, index)
        if raw_start:
            closing = ")" + raw_start.group("delimiter") + '"'
            closing_index = text.find(closing, raw_start.end())
            end = len(text) if closing_index < 0 else closing_index + len(closing)
            _blank_cpp_region(chars, index, end)
            index = end
            continue
        if text.startswith("//", index):
            end = _cpp_line_comment_end(text, index)
            _blank_cpp_region(chars, index, end)
            index = end
            continue
        if text.startswith("/*", index):
            closing_index = text.find("*/", index + 2)
            end = len(text) if closing_index < 0 else closing_index + 2
            _blank_cpp_region(chars, index, end)
            index = end
            continue
        if text[index] in "\"'":
            end = _cpp_quoted_end(text, index)
            _blank_cpp_region(chars, index, end)
            index = end
            continue
        index += 1
    return "".join(chars)

def _exclude_target_sources(sources: list[Path], target: Path) -> list[Path]:
        """Keep source discovery from treating this run's output as input."""

        filtered: list[Path] = []
        for source in sources:
            try:
                source.relative_to(target)
            except ValueError:
                filtered.append(source)
        return filtered

def _ensure_directory_chain(base: Path, path: Path) -> None:
        try:
            parts = path.relative_to(base).parts
        except ValueError as err:
            raise ValueError(f"output path is outside project root: {path}") from err
        current = base
        for part in parts:
            current = current / part
            if current.is_symlink():
                raise ValueError(f"output path contains symlink: {current}")
            if current.exists():
                if not current.is_dir():
                    raise ValueError(f"output path is not a directory: {current}")
            else:
                current.mkdir()

def _ensure_output_file_available(base: Path, path: Path) -> None:
        try:
            path.relative_to(base)
        except ValueError as err:
            raise ValueError(f"output path is outside project root: {path}") from err
        current = path
        while current != base:
            if current.is_symlink():
                raise ValueError(f"output path contains symlink: {current}")
            current = current.parent
        if path.is_symlink():
            raise ValueError(f"output path contains symlink: {path}")
        if path.exists() and not path.is_file():
            raise ValueError(f"output path is not a regular file: {path}")

def _source_relative_path(source: Path, source_dirs: list[Path]) -> Path | None:
        for source_dir in source_dirs:
            try:
                relative = source.relative_to(source_dir)
            except ValueError:
                continue
            if relative.parts:
                return relative
        return None

def _python_entrypoints(
        self, base: Path, project_name: str, targets: list[InspectionTarget]
    ) -> list[tuple[str, str]]:
        build_config = self.config.get("build", {})
        if not isinstance(build_config, dict):
            self._record_error(targets, "build configuration must be a table")
            return []
        python_config = build_config.get("python", {})
        if not isinstance(python_config, dict):
            self._record_error(targets, "build.python configuration must be a table")
            return []
        if "entrypoint" in python_config:
            entrypoint = python_config["entrypoint"]
            if not isinstance(entrypoint, str) or not entrypoint.strip():
                self._record_error(targets, "build.python.entrypoint must be a non-empty string")
                return []
            return [(project_name, entrypoint)]

        try:
            scripts = self._read_project_scripts(base)
        except Exception as exc:
            self._record_error(targets, f"Could not read Python project scripts: {exc}")
            return []
        return sorted(scripts.items())

def _read_project_scripts(base: Path) -> dict[str, str]:
        path = base / "pyproject.toml"
        if not path.exists():
            return {}
        if path.is_symlink():
            raise ValueError("pyproject.toml is a symlink")
        try:
            with path.open("rb") as stream:
                document = tomli.load(stream)
        except (OSError, ValueError, RecursionError, UnicodeError) as exc:
            raise ValueError(f"could not parse pyproject.toml: {exc}") from exc
        if not isinstance(document, dict):
            raise ValueError("pyproject.toml must contain a table")
        project = document.get("project", {})
        if not isinstance(project, dict):
            raise ValueError("pyproject.toml [project] must be a table")
        scripts = project.get("scripts", {})
        if not isinstance(scripts, dict):
            raise ValueError("pyproject.toml [project.scripts] must be a table")
        result: dict[str, str] = {}
        for name, target in scripts.items():
            if not isinstance(name, str) or not isinstance(target, str):
                raise ValueError("project.scripts names and targets must be strings")
            result[name] = target
        return result

def _python_module_exists(self, base: Path, module: str) -> bool:
        try:
            source_dirs = get_source_dirs(base, self.config)
        except Exception:
            return False
        parts = module.split(".")
        for source_dir in source_dirs:
            module_path = source_dir.joinpath(*parts)
            candidates = (module_path.with_suffix(".py"), module_path / "__init__.py")
            for candidate in candidates:
                if candidate.is_symlink() or not candidate.is_file():
                    continue
                try:
                    candidate.resolve(strict=True).relative_to(base)
                except (OSError, RuntimeError, ValueError):
                    continue
                return True
        return False

def _has_build_descriptor(base: Path) -> bool:
        direct_names = {"CMakeLists.txt", "Makefile", "makefile", "GNUmakefile"}
        if any((base / name).is_file() and not (base / name).is_symlink() for name in direct_names):
            return True
        return any(
            path.is_file() and not path.is_symlink()
            for pattern in ("*.pro", "Makefile.*", "*.mk", "*.make")
            for path in base.glob(pattern)
        )

def _count_cpp_main_definitions(
        self, base: Path, sources: list[Path], targets: list[InspectionTarget]
    ) -> tuple[int, bool]:
        count = 0
        inspection_error = False
        for source in sources:
            try:
                text = _mask_cpp_literals(source.read_text(encoding="utf-8"))
            except (OSError, UnicodeError) as exc:
                try:
                    file_path = str(source.relative_to(base))
                except ValueError:
                    file_path = "."
                self._record_error(
                    targets,
                    f"Could not inspect C++ source {source}: {exc}",
                    file_path,
                )
                inspection_error = True
                continue
            count += len(_MAIN_DEFINITION_RE.findall(text))
        return count, inspection_error

def walk(n, nesting: int, in_loop: bool = False):
        nonlocal cognitive, max_nesting
        max_nesting = max(max_nesting, nesting)
        for child in ast.iter_child_nodes(n):
            if isinstance(
                child,
                (
                    ast.If,
                    ast.For,
                    ast.AsyncFor,
                    ast.While,
                    ast.ExceptHandler,
                    ast.With,
                    ast.AsyncWith,
                ),
            ):
                # Each branch/loop/handler/with is +1, weighted by its nesting
                # depth. elif is modeled as a nested If in orelse, so it is
                # counted (and weighted) the same way as any other If.
                cognitive += 1 + nesting
                walk(
                    child,
                    nesting + 1,
                    in_loop or isinstance(child, (ast.For, ast.AsyncFor, ast.While)),
                )
            elif isinstance(child, ast.BoolOp):
                if isinstance(child.op, (ast.And, ast.Or)):
                    cognitive += 1 + nesting
                walk(child, nesting, in_loop)
            elif isinstance(child, ast.comprehension):
                cognitive += 1 + nesting
                walk(child, nesting, in_loop)
            elif isinstance(child, (ast.Break, ast.Continue)):
                if in_loop:
                    cognitive += 1
            elif isinstance(child, ast.Assert):
                cognitive += 1 + nesting
                walk(child, nesting, in_loop)
            else:
                walk(child, nesting, in_loop)

def _calc_ast_cc(self, node: ast.AST) -> int:
        """Calculates Cyclomatic Complexity: 1 + number of branching points."""
        complexity = 1
        for child in ast.walk(node):
            if isinstance(
                child,
                (
                    ast.If,
                    ast.While,
                    ast.For,
                    ast.AsyncFor,
                    ast.ExceptHandler,
                    ast.With,
                    ast.AsyncWith,
                ),
            ):
                complexity += 1
            elif isinstance(child, ast.BoolOp):
                complexity += len(child.values) - 1
            elif isinstance(child, ast.IfExp):
                complexity += 1
            elif isinstance(child, ast.comprehension):
                complexity += len(child.ifs)
            elif isinstance(child, ast.Match):
                complexity += 1 + sum(1 for case in child.cases if case.guard is not None)
        return complexity

def _calc_ast_nesting(self, node: ast.AST) -> int:
        """Calculates maximum block nesting depth inside function."""

        def _get_depth(curr: ast.AST, depth: int) -> int:
            max_d = depth
            is_block = isinstance(
                curr, (ast.If, ast.While, ast.For, ast.AsyncFor, ast.Try, ast.With)
            )
            new_depth = depth + (1 if is_block else 0)
            max_d = max(max_d, new_depth)
            for child in ast.iter_child_nodes(curr):
                max_d = max(max_d, _get_depth(child, new_depth))
            return max_d

        return _get_depth(node, 0)

def _get_depth(curr: ast.AST, depth: int) -> int:
            max_d = depth
            is_block = isinstance(
                curr, (ast.If, ast.While, ast.For, ast.AsyncFor, ast.Try, ast.With)
            )
            new_depth = depth + (1 if is_block else 0)
            max_d = max(max_d, new_depth)
            for child in ast.iter_child_nodes(curr):
                max_d = max(max_d, _get_depth(child, new_depth))
            return max_d

def module_unavailable(result, module: str) -> bool:
    """Accept only a minimal interpreter-level missing-module diagnostic."""

    if result.returncode <= 0 or result.timed_out or result.truncated:
        return False
    lines = [
        line.strip() for line in f"{result.stdout}\n{result.stderr}".splitlines() if line.strip()
    ]
    if len(lines) != 1:
        return False
    missing = rf"No module named ['\"]?{re.escape(module)}['\"]?"
    prefix = (
        rf"(?:python(?:3(?:\.\d+)?)?(?:\.exe)?|"
        rf"(?:[A-Za-z]:[\\/]|/)[^\n]*python(?:3(?:\.\d+)?)?(?:\.exe)?)"
        rf"\s*:\s*{missing}"
    )
    return bool(re.fullmatch(rf"(?:{missing}|{prefix})", lines[0]))

def pytest_result_has_evidence(output: str) -> bool:
    """Return whether pytest output reports an executed result."""

    return bool(
        re.search(r"::\S+\s+(?:PASSED|FAILED|ERROR)\b", output)
        or re.search(r"\b\d+\s+(?:passed|failed|errors?)\b", output)
    )

def _load_coverage_json(json_path: Path) -> dict | None:
    try:
        data = json.loads(json_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    return data if isinstance(data, dict) else None

def _parse_coverage_counts(values: object) -> dict[str, int] | None:
    if not isinstance(values, dict):
        return None
    parsed: dict[str, int] = {}
    for key in _COVERAGE_KEYS:
        value = values.get(key)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            return None
        parsed[key] = value
    if parsed["covered_lines"] > parsed["num_statements"]:
        return None
    if parsed["missing_lines"] > parsed["num_statements"]:
        return None
    if parsed["covered_lines"] + parsed["missing_lines"] != parsed["num_statements"]:
        return None
    if parsed["covered_branches"] > parsed["num_branches"]:
        return None
    return parsed

def _parse_line_numbers(value: object, expected: int) -> list[int] | None:
    if not isinstance(value, list) or len(value) != expected:
        return None
    parsed: list[int] = []
    for item in value:
        if isinstance(item, bool) or not isinstance(item, int) or item <= 0:
            return None
        parsed.append(item)
    if len(set(parsed)) != len(parsed):
        return None
    return parsed

def _parse_coverage_file(
    fname: object, finfo: object, project_root: Path
) -> tuple[str, dict] | None:
    if not isinstance(fname, str) or not isinstance(finfo, dict):
        return None
    executed_lines = finfo.get("executed_lines")
    missing_lines = finfo.get("missing_lines")
    summary = finfo.get("summary")
    if (
        not isinstance(executed_lines, list)
        or not isinstance(missing_lines, list)
        or not isinstance(summary, dict)
    ):
        return None
    parsed_summary = _parse_coverage_counts(summary)
    if parsed_summary is None:
        return None
    parsed_executed = _parse_line_numbers(executed_lines, parsed_summary["covered_lines"])
    parsed_missing = _parse_line_numbers(missing_lines, parsed_summary["missing_lines"])
    if parsed_executed is None or parsed_missing is None:
        return None
    if set(parsed_executed).intersection(parsed_missing):
        return None
    return _relative_coverage_path(fname, project_root), {
        "executed_lines": parsed_executed,
        "missing_lines": parsed_missing,
        "summary": parsed_summary,
    }

def _parse_coverage_files(files: object, project_root: Path) -> dict[str, dict] | None:
    if not isinstance(files, dict) or not files:
        return None
    parsed_files: dict[str, dict] = {}
    for fname, finfo in files.items():
        parsed_file = _parse_coverage_file(fname, finfo, project_root)
        if parsed_file is None:
            return None
        relative, file_data = parsed_file
        if relative in parsed_files:
            return None
        parsed_files[relative] = file_data
    return parsed_files

def _sum_coverage_counts(file_data: dict[str, dict]) -> dict[str, int]:
    totals = {key: 0 for key in _COVERAGE_KEYS}
    for finfo in file_data.values():
        summary = finfo["summary"]
        for key in _COVERAGE_KEYS:
            totals[key] += summary[key]
    return totals

def _build_coverage_result(file_data: dict[str, dict], totals: dict[str, int]) -> dict:
    line_cov = _coverage_percent(totals["covered_lines"], totals["num_statements"])
    branch_cov = _coverage_percent(totals["covered_branches"], totals["num_branches"])
    return {
        "files": file_data,
        "branch_cov": branch_cov,
        "line_cov": line_cov,
        "totals": {
            "stmts": totals["num_statements"],
            "miss": totals["missing_lines"],
            "cover": line_cov,
            "branch_cover": branch_cov,
        },
    }

def _coverage_paths_match(
    file_data: dict[str, dict], expected_files: set[str] | None, project_root: Path
) -> bool:
    if expected_files is None:
        return True
    expected = {_relative_coverage_path(path, project_root) for path in expected_files}
    return set(file_data) == expected

def parse_coverage_json(
    json_path: Path,
    project_root: Path,
    expected_files: set[str] | None = None,
) -> dict | None:
    """Parse coverage.py JSON into strict per-file line and branch data."""

    data = _load_coverage_json(json_path)
    if data is None:
        return None
    totals = _parse_coverage_counts(data.get("totals"))
    file_data = _parse_coverage_files(data.get("files"), project_root)
    if totals is None or file_data is None:
        return None
    if not _coverage_paths_match(file_data, expected_files, project_root):
        return None
    if totals["num_statements"] == 0 or _sum_coverage_counts(file_data) != totals:
        return None
    return _build_coverage_result(file_data, totals)

def _gcov_source_path(gcov_file: Path, source_files: set[str], project_root: Path) -> str | None:
    candidate = gcov_file.name[:-5].replace("#", "/")
    if candidate in source_files:
        return candidate
    try:
        path = Path(candidate)
        absolute = path if path.is_absolute() else project_root / path
        relative = str(absolute.resolve().relative_to(project_root))
    except ValueError:
        return None
    return relative if relative in source_files else None

def parse_gcov_dir(cov_dir: Path, source_files: set[str], project_root: Path) -> list[dict]:
    """Parse gcov branch and line output into per-module coverage rows."""

    rows: list[dict] = []
    for gcov_file in cov_dir.glob("*.gcov"):
        relative = _gcov_source_path(gcov_file, source_files, project_root)
        if relative is None:
            continue

        covered = 0
        miss = 0
        branches = 0
        covered_branches = 0
        missing: list[int] = []
        try:
            content = gcov_file.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue

        for line in content.splitlines():
            if line.startswith("branch"):
                if _EXCEPTION_UNWIND_ARM in line:
                    continue
                parts = line.split()
                branches += 1
                if "taken" in parts:
                    index = parts.index("taken")
                    value = parts[index + 1] if index + 1 < len(parts) else "0"
                    try:
                        if int(value.rstrip("%")) > 0:
                            covered_branches += 1
                    except ValueError as error:
                        _ = error
                continue
            if ":" not in line:
                continue
            parts = line.split(":", 2)
            if len(parts) < 3:
                continue
            count, line_number, _ = parts
            count = count.strip()
            line_number = line_number.strip()
            if count.startswith("-") or not line_number.isdigit():
                continue
            number = int(line_number)
            if count.startswith("#"):
                miss += 1
                missing.append(number)
            else:
                digits = count.rstrip("*")
                if digits.isdigit() and int(digits) > 0:
                    covered += 1

        statements = covered + miss
        if statements == 0:
            continue
        rows.append(
            {
                "file": relative,
                "stmts": statements,
                "covered": covered,
                "miss": miss,
                "cover": round(covered / statements * 100.0, 1) if statements else 100.0,
                "branch_cover": round(covered_branches / branches * 100.0, 1) if branches else None,
                "nb": branches,
                "cb": covered_branches,
                "missing_lines": missing[:30],
            }
        )
    return rows

def compute_python_function_coverage(
    cov_data: dict, project_root: Path, config: dict[str, Any] | None
) -> list[dict]:
    """Mark a Python function covered when one body line executed."""

    rows: list[dict] = []
    file_map = cov_data.get("files", {})
    for py_file in get_all_python_sources(project_root, config):
        relative = str(py_file.relative_to(project_root))
        file_info = file_map.get(relative)
        if not file_info:
            continue
        executed = set(file_info.get("executed_lines") or [])
        missing = set(file_info.get("missing_lines") or [])
        try:
            tree = ast.parse(py_file.read_text(encoding="utf-8"))
        except (SyntaxError, OSError):
            continue
        for node in ast.walk(tree):
            if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            body_start = node.body[0].lineno if node.body else node.lineno
            body_end = node.end_lineno or body_start
            body_lines = set(range(body_start, body_end + 1))
            rows.append(
                {
                    "file": relative,
                    "name": node.name,
                    "start_line": node.lineno,
                    "end_line": body_end,
                    "covered": bool(body_lines & executed),
                    "missing_lines": sorted(body_lines & missing)[:30],
                }
            )
    return rows

def parse_gcov_functions(cov_dir: Path, source_files: set[str], project_root: Path) -> list[dict]:
    """Parse gcov ``function ... called N`` records."""

    rows: list[dict] = []
    for gcov_file in cov_dir.glob("*.gcov"):
        relative = _gcov_source_path(gcov_file, source_files, project_root)
        if relative is None:
            continue
        try:
            content = gcov_file.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        for line in content.splitlines():
            if not line.startswith("function "):
                continue
            parts = line.split()
            if len(parts) < 3:
                continue
            called = 0
            if "called" in parts:
                index = parts.index("called")
                try:
                    called = int(parts[index + 1])
                except (ValueError, IndexError):
                    called = 0
            rows.append(
                {
                    "file": relative,
                    "name": parts[1],
                    "start_line": 1,
                    "end_line": 1,
                    "covered": called > 0,
                    "missing_lines": [],
                }
            )
    return rows

def _python_module_name(py_file: Path, source_dirs: list[Path]) -> str | None:
    """Map a .py file to its dotted module name relative to its source dir."""
    for src_dir in source_dirs:
        try:
            rel = py_file.relative_to(src_dir)
        except ValueError:
            continue
        parts = list(rel.with_suffix("").parts)
        if parts and parts[-1] == "__init__":
            parts = parts[:-1]
        # Use only the last N parts as the module name (relative to src_dir root)
        return ".".join(parts) if parts else None
    return None

def _build_python_graph(
    project_root: Path,
) -> tuple[dict[str, set[str]], dict[str, Path]]:
    """Build module -> imported-module graph for in-project Python sources."""
    from ici.core.project import get_source_dirs

    source_dirs = get_source_dirs(project_root)
    all_sources = get_all_python_sources(project_root)

    file_to_module: dict[Path, str] = {}
    module_to_file: dict[str, Path] = {}
    for py_file in all_sources:
        mod_name = _python_module_name(py_file, source_dirs)
        if mod_name:
            file_to_module[py_file] = mod_name
            module_to_file[mod_name] = py_file

    graph: dict[str, set[str]] = {mod: set() for mod in module_to_file}
    for py_file in all_sources:
        importer = file_to_module.get(py_file)
        if not importer:
            continue
        try:
            tree = ast.parse(py_file.read_text(encoding="utf-8", errors="ignore"))
        except (OSError, SyntaxError):
            continue
        for node in ast.walk(tree):
            targets = []
            if isinstance(node, ast.Import):
                targets = [alias.name for alias in node.names]
            elif isinstance(node, ast.ImportFrom) and node.module:
                targets = [node.module]
            for target_mod in targets:
                # Try exact match, then suffix match (e.g., "b" matches "pkg.b").
                # The suffix fallback exists for flat/relative-style imports, but
                # must never claim a stdlib name (e.g. "html", "json") as a match
                # for an in-project module that merely shares its last segment.
                if target_mod in module_to_file:
                    graph[importer].add(target_mod)
                elif target_mod.split(".")[0] not in sys.stdlib_module_names:
                    for known_mod in module_to_file:
                        if known_mod.endswith("." + target_mod) or known_mod == target_mod:
                            graph[importer].add(known_mod)
    return graph, module_to_file

def _iter_cpp_and_headers(project_root: Path) -> list[Path]:
    """Collect all C++ source + header files inside the project boundary."""
    import os

    skip = {".venv", "venv", "build", ".git"}
    suffixes = {".cpp", ".cc", ".cxx", ".c", ".h", ".hpp", ".hh"}
    results = []
    for current, dir_names, file_names in os.walk(project_root):
        dir_names[:] = [d for d in dir_names if d not in skip]
        current_path = Path(current)
        for name in sorted(file_names):
            path = current_path / name
            if not path.is_symlink() and path.suffix in suffixes:
                results.append(path)
    return results

def _build_cpp_graph(
    project_root: Path,
) -> tuple[dict[Path, set[Path]], dict[Path, Path]]:
    """Build file -> included-file graph including headers.

    ``#include "..."`` is resolved by basename only (no ``-I`` search-path
    model here), so a basename shared by more than one file in the project is
    genuinely ambiguous — silently picking the first one found risks wiring a
    false edge to the wrong file. Ambiguous basenames are left unresolved
    instead.
    """
    all_files = _iter_cpp_and_headers(project_root)
    by_name: dict[str, list[Path]] = {}
    for f in all_files:
        by_name.setdefault(f.name, []).append(f)
    unambiguous = {name: paths[0] for name, paths in by_name.items() if len(paths) == 1}

    graph: dict[Path, set[Path]] = {}
    known: dict[Path, Path] = {}
    for f in all_files:
        resolved_f = f.resolve()
        known[resolved_f] = f
        graph[resolved_f] = set()
        try:
            content = f.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        for match in _INCLUDE_RE.finditer(content):
            inc_name = match.group(1)
            target = unambiguous.get(Path(inc_name).name)
            if target and target.resolve() != resolved_f:
                graph[resolved_f].add(target.resolve())
    return graph, known

def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._analysis_errors: list[str] = []

def _ordered_python_sources(self, source_dirs: list[Path]) -> list[Path]:
        """Return source files in configured root precedence order."""

        sources = get_all_python_sources(self.project_root, self.config)
        ordered: list[Path] = []
        seen: set[Path] = set()
        for source_dir in source_dirs:
            for py_file in sources:
                if py_file in seen:
                    continue
                try:
                    py_file.relative_to(source_dir)
                except ValueError:
                    continue
                ordered.append(py_file)
                seen.add(py_file)
        for py_file in sources:
            if py_file not in seen:
                ordered.append(py_file)
        return ordered

def _private_module_defs(tree: ast.Module) -> dict[str, ast.FunctionDef | ast.AsyncFunctionDef]:
        return {
            node.name: node
            for node in tree.body
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name.startswith("_")
            and not node.name.startswith("__")
        }

def _load_names(tree: ast.AST) -> set[str]:
        return {
            node.id
            for node in ast.walk(tree)
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)
        }

def _qualified_refs(tree: ast.AST, module_name: str) -> set[str]:
        del module_name
        refs: set[str] = set()
        for node in ast.walk(tree):
            if not isinstance(node, ast.Attribute):
                continue
            parts: list[str] = []
            current: ast.AST = node
            while isinstance(current, ast.Attribute):
                parts.append(current.attr)
                current = current.value
            if isinstance(current, ast.Name):
                parts.append(current.id)
                refs.add(".".join(reversed(parts)))
        return refs

def _exports(tree: ast.Module) -> set[str]:
        exported: set[str] = set()
        for node in tree.body:
            if not isinstance(node, (ast.Assign, ast.AnnAssign)):
                continue
            names = node.targets if isinstance(node, ast.Assign) else [node.target]
            if not any(isinstance(name, ast.Name) and name.id == "__all__" for name in names):
                continue
            value = node.value
            if isinstance(value, (ast.List, ast.Tuple, ast.Set)):
                exported.update(
                    item.value
                    for item in value.elts
                    if isinstance(item, ast.Constant) and isinstance(item.value, str)
                )
        return exported

def _imports(
        tree: ast.Module, module_name: str, *, is_package: bool = False
    ) -> dict[str, list[tuple[str, str]]]:
        imports: dict[str, list[tuple[str, str]]] = {}
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom):
                base = DeadCodeEngine._resolve_import_module(
                    module_name, node.module, node.level, is_package=is_package
                )
                for alias in node.names:
                    if alias.name == "*":
                        continue
                    imports.setdefault(alias.asname or alias.name, []).append((base, alias.name))
            elif isinstance(node, ast.Import):
                for alias in node.names:
                    local = alias.asname or alias.name.split(".")[0]
                    imports.setdefault(local, []).append((alias.name, ""))
        return imports

def _resolve_import_module(
        current: str, imported: str | None, level: int, *, is_package: bool = False
    ) -> str:
        if level == 0:
            return imported or ""
        package = current.split(".") if is_package else current.split(".")[:-1]
        if level > 1:
            package = package[: -(level - 1)]
        return ".".join([*package, *(imported.split(".") if imported else [])])

def _module_name(path: Path, source_dirs: list[Path]) -> str:
        for source_dir in source_dirs:
            try:
                relative = path.relative_to(source_dir)
            except ValueError:
                continue
            parts = list(relative.with_suffix("").parts)
            if parts and parts[-1] == "__init__":
                parts.pop()
            return ".".join(parts) or path.stem
        return path.stem

def _resolve_imported_refs(
        self, module: dict, module_paths: dict[str, str]
    ) -> set[tuple[str, str]]:
        resolved: set[tuple[str, str]] = set()
        for alias, bindings in module["imports"].items():
            if alias not in module["refs"]:
                continue
            for imported_module, imported_name in bindings:
                if imported_name:
                    candidate = f"{imported_module}.{imported_name}"
                    if candidate in module_paths:
                        target_id = module_paths[candidate]
                        for reference in module["qualified_refs"]:
                            parts = reference.split(".")
                            if parts[0] == alias and len(parts) > 1:
                                resolved.add((target_id, parts[1]))
                        if not any(
                            reference.split(".", 1)[0] == alias
                            for reference in module["qualified_refs"]
                        ):
                            resolved.add((target_id, imported_name))
                    else:
                        target_id = module_paths.get(imported_module, imported_module)
                        resolved.add((target_id, imported_name))
                    continue
                imported_parts = imported_module.split(".")
                prefix = [alias, *imported_parts[1:]] if imported_parts[0] == alias else [alias]
                for reference in module["qualified_refs"]:
                    parts = reference.split(".")
                    if parts[: len(prefix)] == prefix and len(parts) > len(prefix):
                        target_id = module_paths.get(imported_module, imported_module)
                        resolved.add((target_id, parts[len(prefix)]))
                for module_name in module_paths:
                    if module_name == imported_module or module_name.startswith(
                        imported_module + "."
                    ):
                        resolved.add((module_paths[module_name], ""))
        return resolved

def _append_unreachable_targets(
        self, tree: ast.Module, rel_path: str, targets: list[InspectionTarget]
    ) -> None:
        seen_lists: set[int] = set()
        for node in ast.walk(tree):
            for _field, value in ast.iter_fields(node):
                if not isinstance(value, list) or id(value) in seen_lists:
                    continue
                if not value or not all(isinstance(item, ast.stmt) for item in value):
                    continue
                seen_lists.add(id(value))
                self._check_unreachable(value, rel_path, targets)

def _append_analysis_error(
        self, targets: list[InspectionTarget], path: Path, name: str, message: str, line: int
    ) -> None:
        self._analysis_errors.append(message)
        targets.append(
            InspectionTarget(
                file_path=str(path.relative_to(self.project_root)),
                start_line=line,
                target_name=name,
                status=EngineStatus.ERROR,
                message=message,
            )
        )

def _check_unreachable(
        self, stmts: list[ast.stmt], rel_p: str, targets: list[InspectionTarget]
    ) -> None:
        has_terminator = False
        for stmt in stmts:
            if has_terminator:
                targets.append(
                    InspectionTarget(
                        file_path=rel_p,
                        start_line=stmt.lineno,
                        target_name="UnreachableCode",
                        status=EngineStatus.WARN,
                        message="Unreachable code statement detected after terminal return/raise",
                    )
                )
                break
            if isinstance(stmt, (ast.Return, ast.Raise, ast.Break, ast.Continue)):
                has_terminator = True

def _load_and_index_files(self, all_sources: list[Path]) -> tuple[list[FileData], int]:
        files_data: list[FileData] = []
        total_code_lines = 0

        for src_file in all_sources:
            try:
                rel_p = str(src_file.relative_to(self.project_root))
                with open(src_file, encoding="utf-8", errors="ignore") as f:
                    raw_lines = f.readlines()

                indexed = []
                for idx, r_line in enumerate(raw_lines, 1):
                    s = r_line.strip()
                    if s and not s.startswith(
                        ("#", "//", "/*", "*", "import ", "from ", "#include")
                    ):
                        norm = self._tokenize_line(s)
                        if norm:
                            indexed.append((idx, norm))
                            total_code_lines += 1

                files_data.append((rel_p, raw_lines, indexed))
            except (OSError, UnicodeDecodeError) as err:
                _ = err

        return files_data, total_code_lines

def _find_raw_matches(self, files_data: list[FileData], window_size: int) -> list[MatchPair]:
        """Finds Type-1/Type-2 clones via token windows, greedy extension (same-file)
        and gap-tolerant block matching (cross-file)."""
        window_map: dict[str, list[tuple[int, int]]] = defaultdict(list)
        for f_idx, (_, _, indexed) in enumerate(files_data):
            if len(indexed) < window_size:
                continue
            for t_pos in range(len(indexed) - window_size + 1):
                w_str = "\x00".join(indexed[t_pos + k][1] for k in range(window_size))
                w_hash = hashlib.sha256(w_str.encode("utf-8")).hexdigest()
                window_map[w_hash].append((f_idx, t_pos))

        same_occ: dict[int, list[int]] = defaultdict(list)
        cross_files: set[tuple[int, int]] = set()
        for occs in window_map.values():
            if len(occs) < 2:
                continue
            files_in = {f for f, _ in occs}
            cross_files.update((a, b) for a in files_in for b in files_in if a < b)
            for f, p in occs:
                same_occ[f].append(p)

        raw_matches: list[MatchPair] = []

        # 1. Same-file internal duplication: greedy window extension
        for f_idx, positions in same_occ.items():
            positions = sorted(set(positions))
            if len(positions) < 2:
                continue
            _, _, idx = files_data[f_idx]
            matched: set[tuple[int, int]] = set()
            for i in range(len(positions)):
                p1 = positions[i]
                for j in range(i + 1, len(positions)):
                    p2 = positions[j]
                    if p2 - p1 < window_size:
                        continue
                    if (p1, p2) in matched:
                        continue
                    k = 0
                    while p1 + k < p2 and p2 + k < len(idx) and idx[p1 + k][1] == idx[p2 + k][1]:
                        matched.add((p1 + k, p2 + k))
                        k += 1
                    if k >= window_size:
                        raw_matches.append(
                            (
                                f_idx,
                                idx[p1][0],
                                idx[p1 + k - 1][0],
                                f_idx,
                                idx[p2][0],
                                idx[p2 + k - 1][0],
                                k,
                            )
                        )

        # 2. Cross-file duplication: gap-tolerant SequenceMatcher blocks
        for f1, f2 in sorted(cross_files):
            _, _, idx1 = files_data[f1]
            _, _, idx2 = files_data[f2]
            seq1 = [norm for _, norm in idx1]
            seq2 = [norm for _, norm in idx2]
            sm = difflib.SequenceMatcher(None, seq1, seq2, autojunk=False)
            for block in sm.get_matching_blocks():
                if block.size < window_size:
                    continue
                raw_matches.append(
                    (
                        f1,
                        idx1[block.a][0],
                        idx1[block.a + block.size - 1][0],
                        f2,
                        idx2[block.b][0],
                        idx2[block.b + block.size - 1][0],
                        block.size,
                    )
                )

        return raw_matches

def _filter_subsumed_matches(self, raw_matches: list[MatchPair]) -> list[MatchPair]:
        """Keeps maximal clones: drops matches overlapping a larger kept match on both sides."""
        raw_matches.sort(key=lambda x: x[6], reverse=True)
        filtered: list[MatchPair] = []

        for match in raw_matches:
            f1, s1, e1, f2, s2, e2, _ = match
            redundant = False
            for pf1, ps1, pe1, pf2, ps2, pe2, _ in filtered:
                if f1 != pf1 or f2 != pf2:
                    continue
                overlaps_1 = not (e1 < ps1 or s1 > pe1)
                overlaps_2 = not (e2 < ps2 or s2 > pe2)
                if overlaps_1 and overlaps_2:
                    redundant = True
                    break
            if not redundant:
                filtered.append(match)

        return filtered

def _tokenize_line(self, line: str) -> str:
        """Normalizes identifiers to ID and literals to LIT (Type-2 clone support)."""

        def _repl(match: re.Match) -> str:
            tok = match.group(0)
            if tok.startswith(("'", '"')):
                return "LIT"
            if tok[0].isdigit():
                return "LIT"
            return tok if tok in _STRUCT_KEYWORDS else "ID"

        tokenized = _TOKEN_RE.sub(_repl, line)
        return "".join(c for c in tokenized if not c.isspace())

def _repl(match: re.Match) -> str:
            tok = match.group(0)
            if tok.startswith(("'", '"')):
                return "LIT"
            if tok[0].isdigit():
                return "LIT"
            return tok if tok in _STRUCT_KEYWORDS else "ID"

def visit_ExceptHandler(self, node: ast.ExceptHandler) -> None:
        if node is not self.handler and node.name == self.alias:
            return
        self.generic_visit(node)

def visit_Raise(self, node: ast.Raise) -> None:
        if isinstance(node.exc, ast.Name) and node.exc.id == self.alias and node.cause is None:
            self.raises.append(node)
        self.generic_visit(node)

def _visit_conditional_nodes(self, nodes: Iterable[ast.AST]) -> None:
        self._conditional_depth += 1
        for node in nodes:
            self.visit(node)
        self._conditional_depth -= 1

def visit_For(self, node: ast.For) -> None:
        self.visit(node.iter)
        self._visit_conditional_nodes([node.target, *node.body, *node.orelse])

def visit_AsyncFor(self, node: ast.AsyncFor) -> None:
        self.visit(node.iter)
        self._visit_conditional_nodes([node.target, *node.body, *node.orelse])

def visit_With(self, node: ast.With) -> None:
        for index, item in enumerate(node.items):
            if index == 0:
                self.visit(item.context_expr)
            else:
                self._visit_conditional_nodes([item.context_expr])
            if item.optional_vars is not None:
                self._visit_conditional_nodes([item.optional_vars])
        self._visit_conditional_suite(node.body)

def visit_AsyncWith(self, node: ast.AsyncWith) -> None:
        for index, item in enumerate(node.items):
            if index == 0:
                self.visit(item.context_expr)
            else:
                self._visit_conditional_nodes([item.context_expr])
            if item.optional_vars is not None:
                self._visit_conditional_nodes([item.optional_vars])
        self._visit_conditional_suite(node.body)

def visit_BoolOp(self, node: ast.BoolOp) -> None:
        if node.values:
            self.visit(node.values[0])
            self._visit_conditional_nodes(node.values[1:])

def visit_IfExp(self, node: ast.IfExp) -> None:
        self.visit(node.test)
        self._visit_conditional_nodes([node.body, node.orelse])

def visit_Match(self, node: ast.Match) -> None:
        self.visit(node.subject)
        definite_capture = (
            len(node.cases) == 1
            and node.cases[0].guard is None
            and self._is_irrefutable_capture(node.cases[0].pattern)
        )
        for case in node.cases:
            self._conditional_depth += 1
            capture_kind = "match_definite" if definite_capture else "match"
            for name, capture in self._match_captures(case.pattern):
                self._record(name, capture_kind, capture)
            if case.guard is not None:
                self.visit(case.guard)
            for statement in case.body:
                self.visit(statement)
            self._conditional_depth -= 1

def _match_captures(pattern: ast.pattern) -> list[tuple[str, ast.AST]]:
        captures: list[tuple[str, ast.AST]] = []
        for node in ast.walk(pattern):
            if isinstance(node, (ast.MatchAs, ast.MatchStar)) and node.name:
                captures.append((node.name, node))
            elif isinstance(node, ast.MatchMapping) and node.rest:
                captures.append((node.rest, node))
        return captures

def visit_ExceptHandler(self, node: ast.ExceptHandler) -> None:
        if node.type is not None:
            self.visit(node.type)
        self._visit_conditional_suite(node.body)

def _visit_arguments(self, arguments: ast.arguments) -> None:
        argument_nodes = arguments.posonlyargs + arguments.args + arguments.kwonlyargs
        for argument in argument_nodes:
            self._record(argument.arg, "shadow", argument)
        if arguments.vararg is not None:
            self._record(arguments.vararg.arg, "shadow", arguments.vararg)
        if arguments.kwarg is not None:
            self._record(arguments.kwarg.arg, "shadow", arguments.kwarg)

def _visit_function(self, node: ast.FunctionDef | ast.AsyncFunctionDef) -> None:
        if node is self.scope:
            self._visit_arguments(node.args)
            self.generic_visit(node)
        else:
            self._record(node.name, "shadow", node)

def visit_ClassDef(self, node: ast.ClassDef) -> None:
        if node is self.scope:
            self.generic_visit(node)
        else:
            self._record(node.name, "shadow", node)

def visit_Name(self, node: ast.Name) -> None:
        if isinstance(node.ctx, ast.Del):
            self._record(node.id, "delete", node)
        elif isinstance(node.ctx, ast.Store):
            self._record(node.id, "shadow", node)

def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            local_name = alias.asname or alias.name.split(".")[0]
            kind = "builtins" if alias.name == "builtins" else "shadow"
            self._record(local_name, kind, node)

def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        for alias in node.names:
            if alias.name == "*":
                continue
            local_name = alias.asname or alias.name
            kind = "shadow"
            if node.module == "builtins" and alias.name == "BaseException":
                kind = "exception"
            self._record(local_name, kind, node)

def _bindings_before(self, cutoff: tuple[int, int] | None) -> dict[str, set[str]]:
        bindings: dict[str, set[str]] = {}
        for position, name, kind, conditional in sorted(self.events):
            if cutoff is not None and position[:2] >= cutoff:
                continue
            if conditional:
                bindings.setdefault(name, {"unbound"}).add(kind)
            else:
                bindings[name] = {kind}
        return bindings

def _effective_aliases(
        bindings: dict[str, set[str]],
    ) -> tuple[set[str], set[str], set[str]]:
        return (
            {name for name, kinds in bindings.items() if "exception" in kinds},
            {name for name, kinds in bindings.items() if "builtins" in kinds},
            {
                name
                for name, kinds in bindings.items()
                if (
                    (
                        "shadow" in kinds
                        and "unbound" not in kinds
                        and "exception" not in kinds
                        and "builtins" not in kinds
                        and not ("delete" in kinds and name == "BaseException")
                    )
                    or ("match_definite" in kinds)
                    or ("delete" in kinds and name != "BaseException")
                )
            },
        )

def _possible_aliases(
        self,
        bindings: dict[str, set[str]],
        cutoff: tuple[int, int],
        possible_after: bool,
    ) -> tuple[set[str], set[str], set[str]]:
        exception_aliases, builtins_aliases, _ = self._effective_aliases(bindings)
        if possible_after:
            for position, name, kind, _ in self.events:
                if position[:2] < cutoff:
                    continue
                if kind == "exception":
                    exception_aliases.add(name)
                elif kind == "builtins":
                    builtins_aliases.add(name)
        shadowed_names = {
            name
            for name, kinds in bindings.items()
            if name not in exception_aliases
            and name not in builtins_aliases
            and (
                (
                    "shadow" in kinds
                    and "unbound" not in kinds
                    and not ("delete" in kinds and name == "BaseException")
                )
                or "match_definite" in kinds
                or ("delete" in kinds and name != "BaseException")
            )
        }
        return exception_aliases, builtins_aliases, shadowed_names

def _bound_names(
        self,
        handler: ast.ExceptHandler | None,
        cutoff: tuple[int, int] | None,
    ) -> set[str]:
        if handler is None or not self._is_function_scope:
            return set()
        handler_name = handler.name
        return {
            name
            for position, name, _, _ in self.events
            if name not in self._global_names
            and name not in self._nonlocal_names
            and not (handler_name is not None and position[:2] == cutoff and name == handler_name)
        }

def _handler_position(handler: ast.ExceptHandler | None) -> tuple[int, int] | None:
        if handler is None:
            return None
        return handler.lineno, handler.col_offset

def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._analysis_errors: list[str] = []

def _is_swallowed(node: ast.ExceptHandler) -> bool:
        if len(node.body) != 1:
            return False
        statement = node.body[0]
        return isinstance(statement, ast.Pass) or (
            isinstance(statement, ast.Expr)
            and isinstance(statement.value, ast.Constant)
            and statement.value.value is Ellipsis
        )

def _parent_map(tree: ast.AST) -> dict[ast.AST, ast.AST]:
        return {
            child: parent for parent in ast.walk(tree) for child in ast.iter_child_nodes(parent)
        }

def _transient_handler_bindings(
        node: ast.ExceptHandler,
        parent_map: dict[ast.AST, ast.AST],
        active_scopes: list[ast.AST],
    ) -> dict[ast.AST, TransientEvents]:
        scope_indexes = {scope: index for index, scope in enumerate(active_scopes)}
        bindings: dict[ast.AST, TransientEvents] = {}
        current = parent_map.get(node)
        while current is not None:
            if isinstance(current, ast.ExceptHandler) and current.name:
                owner = parent_map.get(current)
                while owner is not None and not isinstance(
                    owner,
                    (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef),
                ):
                    owner = parent_map.get(owner)
                if owner in scope_indexes:
                    position = (current.lineno, current.col_offset, -1)
                    bindings.setdefault(owner, []).append((current.name, position))
            current = parent_map.get(current)
        return bindings

def _child_scope_cutoff(scope: ast.AST) -> tuple[int, int] | None:
        if isinstance(scope, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            return scope.lineno, scope.col_offset
        return None

def _scope_aliases(
        scope: ast.AST,
        handler: ast.ExceptHandler | None,
        cutoff: tuple[int, int] | None = None,
        possible_after: bool = False,
        transient_events: TransientEvents | None = None,
    ) -> ScopeAliases:
        collector = _ScopeAliasCollector(scope)
        collector.visit(scope)
        for name, position in transient_events or ():
            collector.events.append((position, name, "shadow", False))
        return collector.resolve(handler, cutoff, possible_after)

def _is_base_exception_type(
        node: ast.expr,
        scope_aliases: list[ScopeAliases],
    ) -> bool:
        if isinstance(node, ast.Name):
            if node.id == "BaseException":
                return ExceptionSafetyEngine._resolves_direct_base_exception(scope_aliases)
            return ExceptionSafetyEngine._resolves_alias(
                node.id, scope_aliases, alias_kind="exception"
            )
        if isinstance(node, ast.Attribute):
            return (
                node.attr == "BaseException"
                and isinstance(node.value, ast.Name)
                and ExceptionSafetyEngine._resolves_alias(
                    node.value.id, scope_aliases, alias_kind="builtins"
                )
            )
        if isinstance(node, (ast.Tuple, ast.List)):
            return any(
                ExceptionSafetyEngine._is_base_exception_type(item, scope_aliases)
                for item in node.elts
            )
        return False

def _resolves_direct_base_exception(
        scope_aliases: list[ScopeAliases],
    ) -> bool:
        for exception_aliases, _, shadowed, bound_names in reversed(scope_aliases):
            if "BaseException" in exception_aliases:
                return True
            if "BaseException" in shadowed or "BaseException" in bound_names:
                return False
        return True

def _resolves_alias(
        name: str,
        scope_aliases: list[ScopeAliases],
        *,
        alias_kind: str,
    ) -> bool:
        for exception_aliases, builtins_aliases, shadowed, bound_names in reversed(scope_aliases):
            aliases = exception_aliases if alias_kind == "exception" else builtins_aliases
            if name in aliases:
                return True
            if name in shadowed or name in bound_names:
                return False
        return False

def _mask_cpp_literals(content: str) -> str:
        chars = list(content)
        index = 0
        state = "code"
        while index < len(chars):
            index, state = ExceptionSafetyEngine._mask_cpp_step(content, chars, index, state)
        return "".join(chars)

def _mask_cpp_step(content: str, chars: list[str], index: int, state: str) -> tuple[int, str]:
        if state == "code":
            return ExceptionSafetyEngine._mask_cpp_code_step(content, chars, index)
        if state == "line":
            return ExceptionSafetyEngine._mask_cpp_line_step(chars, index)
        if state == "line_splice":
            return ExceptionSafetyEngine._mask_cpp_line_splice_step(chars, index)
        if state == "block":
            return ExceptionSafetyEngine._mask_cpp_block_step(chars, index)
        return ExceptionSafetyEngine._mask_cpp_quote_step(chars, index, state)

def _mask_cpp_code_step(content: str, chars: list[str], index: int) -> tuple[int, str]:
        following = chars[index + 1] if index + 1 < len(chars) else ""
        raw_end = ExceptionSafetyEngine._cpp_raw_string_end(content, index)
        if raw_end is not None:
            ExceptionSafetyEngine._blank_cpp_span(chars, index, raw_end)
            return raw_end, "code"
        if following == "/" and chars[index] == "/":
            chars[index] = chars[index + 1] = " "
            return index + 2, "line"
        if following == "*" and chars[index] == "/":
            chars[index] = chars[index + 1] = " "
            return index + 2, "block"
        quote = chars[index]
        if quote in {'"', "'"}:
            chars[index] = " "
            return index + 1, quote
        if chars[index] == "\\":
            return ExceptionSafetyEngine._blank_cpp_escape(chars, index), "code"
        return index + 1, "code"

def _mask_cpp_line_step(chars: list[str], index: int) -> tuple[int, str]:
        if chars[index] == "\\" and index + 1 < len(chars):
            following = chars[index + 1]
            if following == "\n" or (
                following == "\r" and index + 2 < len(chars) and chars[index + 2] == "\n"
            ):
                chars[index] = " "
                return index + 1, "line_splice"
        if chars[index] == "\n":
            return index + 1, "code"
        chars[index] = " "
        return index + 1, "line"

def _mask_cpp_line_splice_step(chars: list[str], index: int) -> tuple[int, str]:
        if chars[index] == "\r" and index + 1 < len(chars) and chars[index + 1] == "\n":
            return index + 2, "line"
        if chars[index] == "\n":
            return index + 1, "line"
        return ExceptionSafetyEngine._mask_cpp_line_step(chars, index)

def _mask_cpp_block_step(chars: list[str], index: int) -> tuple[int, str]:
        following = chars[index + 1] if index + 1 < len(chars) else ""
        if chars[index] == "*" and following == "/":
            chars[index] = chars[index + 1] = " "
            return index + 2, "code"
        if chars[index] != "\n":
            chars[index] = " "
        return index + 1, "block"

def _mask_cpp_quote_step(chars: list[str], index: int, state: str) -> tuple[int, str]:
        current = chars[index]
        if current == "\\":
            return ExceptionSafetyEngine._blank_cpp_escape(chars, index), state
        if current == state:
            return index + 1, "code"
        if current != "\n":
            chars[index] = " "
        return index + 1, state

def _blank_cpp_escape(chars: list[str], index: int) -> int:
        chars[index] = " "
        if index + 1 < len(chars) and chars[index + 1] != "\n":
            chars[index + 1] = " "
            return index + 2
        return index + 1

def _cpp_raw_string_end(content: str, index: int) -> int | None:
        if content[index : index + 2] != 'R"':
            return None
        open_paren = content.find("(", index + 2)
        if open_paren == -1:
            return None
        delimiter = content[index + 2 : open_paren]
        if len(delimiter) > 16 or any(
            char.isspace() or char in {"\\", "(", ")"} for char in delimiter
        ):
            return None
        close_marker = ")" + delimiter + '"'
        close_start = content.find(close_marker, open_paren + 1)
        return len(content) if close_start == -1 else close_start + len(close_marker)

def _blank_cpp_span(chars: list[str], start: int, end: int) -> None:
        for position in range(start, end):
            if chars[position] != "\n":
                chars[position] = " "

def _empty_catch_all_lines(masked: str) -> list[int]:
        pattern = re.compile(r"catch\s*\(\s*\.\.\.\s*\)\s*\{(?P<body>.*?)\}", re.DOTALL)
        return [
            masked[: match.start()].count("\n") + 1
            for match in pattern.finditer(masked)
            if not match.group("body").strip()
        ]

def _classify(
        self, code: int, is_gated: bool, warn: int, fail: int
    ) -> tuple[EngineStatus, str]:
        """Applies single-file size thresholds to gated source files only."""
        if is_gated and fail is not None and code > fail:
            return EngineStatus.FAIL, (
                f"Pure code lines ({code}) exceed {fail} lines limit (Refactoring required)"
            )
        if is_gated and warn is not None and code > warn:
            return EngineStatus.WARN, (
                f"Pure code lines ({code}) exceed {warn} lines threshold (Split recommended)"
            )
        return EngineStatus.PASS, f"{code} code lines"

def _acceptable(self, filepath: Path) -> bool:
        return (
            not filepath.is_symlink()
            and filepath.is_file()
            and filepath.suffix in EXT_MAP
            and not _should_ignore_path(filepath)
        )

def _collect_files(self, plan: dict) -> dict:
        """Pass 1 scans source scope; pass 2 sweeps the whole project for extras."""
        data = self._fresh_accumulator()
        data.update(
            gate_set=plan["gate_set"], warn_limit=plan["warn_limit"], fail_limit=plan["fail_limit"]
        )

        for d in plan["scope_list"]:
            dir_path = self.project_root / d
            if not dir_path.exists():
                continue
            for filepath in sorted(dir_path.rglob("*")):
                if filepath in data["seen"] or not self._acceptable(filepath):
                    continue
                data["seen"].add(filepath)
                self._record_file(data, filepath, True)

        for current, dir_names, file_names in os.walk(self.project_root):
            cur_path = Path(current)
            dir_names[:] = [
                x
                for x in dir_names
                if x not in _JUNK_DIRS and (cur_path / x) not in plan["exclude_roots"]
            ]
            if any(cur_path == root or root in cur_path.parents for root in plan["exclude_roots"]):
                continue
            for name in sorted(file_names):
                filepath = cur_path / name
                if filepath in data["seen"] or not self._acceptable(filepath):
                    continue
                data["seen"].add(filepath)
                self._record_file(data, filepath, False)

        return data

def _count_file(self, filepath: Path) -> tuple[int, int, int]:
        code, comment, blank = 0, 0, 0
        in_block_comment = False

        try:
            with open(filepath, encoding="utf-8", errors="ignore") as f:
                for line in f:
                    stripped = line.strip()
                    if not stripped:
                        blank += 1
                        continue

                    if filepath.suffix in (".cpp", ".c", ".h", ".hpp", ".cc", ".cxx"):
                        if in_block_comment:
                            comment += 1
                            if "*/" in stripped:
                                in_block_comment = False
                            continue
                        if stripped.startswith("/*"):
                            comment += 1
                            if "*/" not in stripped:
                                in_block_comment = True
                            continue
                        if stripped.startswith("//"):
                            comment += 1
                            continue
                    elif filepath.suffix in (".py", ".sh", ".csh", ".toml", ".yml", ".yaml"):
                        if stripped.startswith("#"):
                            comment += 1
                            continue

                    code += 1
        except (OSError, UnicodeDecodeError) as err:
            # Unreadable/undecodable files contribute nothing; keep counting others.
            _ = err

        return code, comment, blank

def _record_missing_tool(evidence: list[ToolEvidence], name: str) -> None:
        evidence.append(
            ToolEvidence(
                name=name,
                path="",
                error="tool not found; no command was executed",
            )
        )

def _record_tool_exception(
        evidence: list[ToolEvidence], name: str, command: list[str], exc: Exception
    ) -> None:
        evidence.append(
            ToolEvidence(
                name=name,
                path=command[0],
                argv=command,
                error=f"{type(exc).__name__}: {exc}",
            )
        )

def _find_ruff_command(self) -> list[str] | None:
        which_ruff = shutil.which("ruff")
        if which_ruff:
            return [which_ruff]
        venv_ruff = find_project_executable(self.project_root, "ruff")
        if venv_ruff:
            return [venv_ruff]
        return None

def _evaluate_ruff_check(
        self,
        result: ProcessResult,
        targets: list[InspectionTarget],
        tool_warnings: list[str] | None = None,
    ) -> list[str]:
        if result.timed_out:
            return ["Ruff check timed out"]
        if result.truncated:
            return ["Ruff check output was truncated"]
        if not isinstance(result.returncode, int) or result.returncode < 0:
            return ["Ruff check terminated before producing a result"]
        if result.returncode not in (0, 1):
            return [f"Ruff check failed with exit code {result.returncode}"]
        warnings, warning_error = _parse_ruff_warning_blocks(result.stderr)
        if warning_error:
            return [f"Ruff check emitted unexpected stderr: {warning_error}"]
        if tool_warnings is not None:
            tool_warnings.extend(warnings)
        if not result.stdout.strip():
            message = "violations" if result.returncode == 1 else "succeeded"
            return [f"Ruff check {message} without parseable JSON"]
        try:
            issues = json.loads(result.stdout)
            if not isinstance(issues, list):
                raise ValueError("Ruff JSON output is not a list")
            if result.returncode == 0 and issues:
                return ["Ruff check returned success with diagnostic findings"]
            if result.returncode == 1 and not issues:
                return ["Ruff reported violations without any JSON findings"]
            targets.extend(self._parse_ruff_findings(issues))
        except (json.JSONDecodeError, ValueError) as error:
            return [f"Ruff check output was not valid JSON: {error}"]
        return []

def _parse_ruff_findings(self, issues: list[object]) -> list[InspectionTarget]:
        parsed: list[InspectionTarget] = []
        for item in issues:
            if not isinstance(item, dict):
                raise ValueError("Ruff JSON item is not an object")
            fpath = item.get("filename", "")
            if not isinstance(fpath, str) or not fpath.strip():
                raise ValueError("Ruff JSON filename is missing")
            code = item.get("code", "RUFF")
            message = item.get("message", "")
            if not isinstance(code, str) or not code.strip():
                raise ValueError("Ruff JSON code is missing")
            if not isinstance(message, str) or not message.strip():
                raise ValueError("Ruff JSON message is missing")
            try:
                rel_path = str(Path(fpath).relative_to(self.project_root))
            except (TypeError, ValueError):
                rel_path = str(fpath)
            location = item.get("location", {})
            if not isinstance(location, dict):
                raise ValueError("Ruff JSON location is not an object")
            row = location.get("row")
            if isinstance(row, bool) or not isinstance(row, int) or row < 1:
                raise ValueError("Ruff JSON row is invalid")
            parsed.append(
                InspectionTarget(
                    file_path=rel_path,
                    start_line=row,
                    target_name=f"Ruff:{code}",
                    status=EngineStatus.FAIL,
                    message=message,
                )
            )
        return parsed

def _run_ruff_format(
        self,
        ruff_cmd: list[str],
        targets: list[InspectionTarget],
        evidence: list[ToolEvidence],
        tool_warnings: list[str] | None = None,
    ) -> list[str]:
        warnings = tool_warnings if tool_warnings is not None else []
        supports_json, probe_error = self._probe_ruff_format_json_support(
            ruff_cmd, evidence, warnings
        )
        if probe_error:
            return [probe_error]

        command = [*ruff_cmd, "format", "--check", "."]
        if supports_json:
            command = [*ruff_cmd, "format", "--check", "--output-format=json", "."]
        try:
            result = run_process(command, cwd=self.project_root)
        except Exception as exc:
            self._record_tool_exception(evidence, "ruff format", command, exc)
            return [f"Ruff format could not execute: {type(exc).__name__}: {exc}"]
        tool_record = self._record_process(evidence, "ruff format", command, result)
        errors = self._evaluate_ruff_format(result, targets, warnings, json_output=supports_json)
        if errors:
            tool_record.error = errors[0]
        return errors

def _evaluate_ruff_format(
        self,
        result: ProcessResult,
        targets: list[InspectionTarget],
        tool_warnings: list[str] | None = None,
        *,
        json_output: bool = False,
    ) -> list[str]:
        if result.timed_out:
            return ["Ruff format check timed out"]
        if result.truncated:
            return ["Ruff format output was truncated"]
        if not isinstance(result.returncode, int) or result.returncode < 0:
            return ["Ruff format check terminated before producing a result"]
        if result.returncode not in (0, 1):
            return [f"Ruff format check failed with exit code {result.returncode}"]
        warnings, warning_error = _parse_ruff_warning_blocks(result.stderr)
        if warning_error:
            return [f"Ruff format emitted unexpected stderr: {warning_error}"]
        if tool_warnings is not None:
            tool_warnings.extend(warnings)
        if json_output:
            return self._evaluate_ruff_format_json(result, targets)
        if result.returncode == 1 and not result.stdout:
            return ["Ruff format check failed without diagnostic output"]
        if result.returncode == 0 and not self._is_valid_format_success(result):
            return ["Ruff format output was not parseable"]
        if result.returncode == 1 and not self._append_reformat_targets(result, targets):
            return ["Ruff format output was not parseable"]
        return []

def _evaluate_ruff_format_json(
        self, result: ProcessResult, targets: list[InspectionTarget]
    ) -> list[str]:
        try:
            diagnostics = json.loads(result.stdout)
            if not isinstance(diagnostics, list):
                raise ValueError("Ruff format JSON output is not a list")
        except (json.JSONDecodeError, ValueError) as error:
            return [f"Ruff format output was not parseable as JSON: {error}"]

        if result.returncode == 0:
            if diagnostics:
                return ["Ruff format returned success with diagnostic findings"]
            return []
        if not diagnostics:
            return ["Ruff format reported violations without any JSON findings"]

        try:
            parsed = self._parse_ruff_format_diagnostics(diagnostics)
        except ValueError as error:
            return [f"Ruff format output was not parseable: {error}"]
        targets.extend(parsed)
        return []

def _parse_ruff_format_diagnostics(self, diagnostics: list[object]) -> list[InspectionTarget]:
        parsed: list[InspectionTarget] = []
        for item in diagnostics:
            if not isinstance(item, dict):
                raise ValueError("Ruff format JSON item is not an object")
            filename = item.get("filename")
            if not isinstance(filename, str) or not filename.strip():
                raise ValueError("Ruff format JSON filename is missing")
            if item.get("code") != "unformatted":
                raise ValueError("Ruff format JSON code is not unformatted")
            location = item.get("location")
            if not isinstance(location, dict):
                raise ValueError("Ruff format JSON location is not an object")
            row = location.get("row")
            if isinstance(row, bool) or not isinstance(row, int) or row < 1:
                raise ValueError("Ruff format JSON row is invalid")
            column = location.get("column")
            if column is not None and (
                isinstance(column, bool) or not isinstance(column, int) or column < 1
            ):
                raise ValueError("Ruff format JSON column is invalid")
            message = item.get("message", "File requires reformatting (PEP 8 style mismatch)")
            if not isinstance(message, str) or not message.strip():
                raise ValueError("Ruff format JSON message is invalid")
            try:
                rel_path = str(Path(filename).relative_to(self.project_root))
            except (TypeError, ValueError):
                rel_path = str(filename)
            parsed.append(
                InspectionTarget(
                    file_path=rel_path,
                    start_line=row,
                    target_name="Format:Style",
                    status=EngineStatus.WARN,
                    message=message,
                )
            )
        return parsed

def _is_valid_format_success(result: ProcessResult) -> bool:
        return (
            not result.stdout.strip()
            or _RUFF_FORMAT_SUCCESS_RE.fullmatch(result.stdout) is not None
        )

def _check_python_syntax(self, targets: list[InspectionTarget]) -> None:
        for py_file in self.project_root.rglob("*.py"):
            if _should_ignore_path(py_file):
                continue
            try:
                ast.parse(py_file.read_text(encoding="utf-8"), filename=str(py_file))
            except SyntaxError as error:
                targets.append(
                    InspectionTarget(
                        file_path=str(py_file.relative_to(self.project_root)),
                        start_line=error.lineno or 1,
                        target_name="SyntaxError",
                        status=EngineStatus.FAIL,
                        message=f"SyntaxError: {error.msg}",
                    )
                )

def _parse_cpp_diagnostics(
        self, stdout: str, stderr: str
    ) -> tuple[list[InspectionTarget], bool, bool]:
        parsed: list[InspectionTarget] = []
        malformed = False
        found_diagnostic = False
        for raw_line in (stdout + "\n" + stderr).splitlines():
            line = raw_line.strip()
            if not line:
                continue
            match = _CPP_DIAGNOSTIC_RE.match(line)
            if match:
                found_diagnostic = True
                kind = match.group("kind")
                file_path = self._diagnostic_path(match.group("file"))
                parsed.append(
                    InspectionTarget(
                        file_path=file_path,
                        start_line=int(match.group("line")),
                        target_name="C++Syntax",
                        status=EngineStatus.FAIL if "error" in kind else EngineStatus.WARN,
                        message=f"{kind}: {match.group('message')}",
                    )
                )
                continue
            if line.startswith("In file included from") or line.startswith("from "):
                continue
            if found_diagnostic and self._is_cpp_context(line):
                continue
            if _CPP_CONTEXT_HEADER_RE.fullmatch(line) or _CPP_REQUIRED_FROM_RE.fullmatch(line):
                continue
            malformed = True
        return parsed, malformed, found_diagnostic

def _diagnostic_path(self, value: str) -> str:
        path = Path(value.strip())
        try:
            return str(path.relative_to(self.project_root))
        except ValueError:
            if path.is_absolute():
                return str(path)
            return str(path)

def _report_link_lines(
