    if run_url:
        parts.append(f"[⚙️ Workflow Run]({run_url})")
    parts.append("<sub>generated by ici</sub>")
    return "<br/>".join(parts)

def load_suite_from_json(json_path: Path) -> VerificationSuiteResult | None:
    """Reconstruct a lightweight suite from an ``ici.result/v2`` report file."""
    try:
        payload = json.loads(Path(json_path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    if not isinstance(payload, dict) or not isinstance(payload.get("results"), list):
        return None

    results = []
    for item in payload["results"]:
        if not isinstance(item, dict):
            continue
        try:
            results.append(
                EngineResult(
                    engine_name=str(item.get("engine_name", "?")),
                    status=EngineStatus(str(item.get("status", "SKIP"))),
                    summary=str(item.get("summary", "")),
                    score=item.get("score"),
                    max_score=item.get("max_score"),
                    duration=float(item.get("duration", 0.0)),
                )
            )
        except (ValueError, TypeError):
            continue

    suite_status_raw = str(payload.get("suite_status", "WARN"))
    try:
        suite_status = EngineStatus(suite_status_raw)
    except ValueError:
        suite_status = EngineStatus.WARN

    tem = payload.get("tem_score")
    max_tem = payload.get("max_tem_score", 5.0)
    return VerificationSuiteResult(
        suite_status=suite_status,
        results=results,
        duration=float(payload.get("duration", 0.0)),
        tem_score=float(tem) if isinstance(tem, (int, float)) else None,
        max_tem_score=float(max_tem) if isinstance(max_tem, (int, float)) else 5.0,
    )

def __init__(self, env: dict[str, str] | None = None, project_name: str | None = None):
        self.env = env if env is not None else dict(os.environ)
        self.project_name = project_name

def _resolve_target(
        self,
    ) -> tuple[str, str, str, str, str, int | None, str | None] | None:
        hub_repo = self.env.get("ICI_PUBLISH_REPO", "").strip()
        hub_token = self.env.get("ICI_PUBLISH_TOKEN", "").strip()
        own_repo = self.env.get("GITHUB_REPOSITORY", "").strip()
        own_token = self.env.get("GITHUB_TOKEN", "").strip()
        branch = self.env.get("ICI_PUBLISH_BRANCH", "").strip() or "gh-pages"

        if hub_repo:
            mode = "hub"
            repo = hub_repo
            token = hub_token or own_token
            prefix = (self.project_name or own_repo.rsplit("/", 1)[-1] or "project").replace(
                "/", "-"
            )
        elif own_repo:
            mode = "self"
            repo = own_repo
            token = own_token
            prefix = ""
        else:
            return None

        if not token:
            return None

        pr_number = self._detect_pr_number()
        ref_name = self.env.get("GITHUB_REF_NAME", "").strip()
        if pr_number:
            sub_path = f"pr/{pr_number}/index.html"
        elif ref_name in ("main", "master"):
            sub_path = "main/index.html"
        elif ref_name:
            sub_path = f"branch/{ref_name.replace('/', '-')}/index.html"
        else:
            sub_path = "index.html"

        remote_path = f"{prefix}/{sub_path}" if prefix else sub_path
        run_url = None
        server_url = self.env.get("GITHUB_SERVER_URL", "").strip()
        run_id = self.env.get("GITHUB_RUN_ID", "").strip()
        if server_url and own_repo and run_id:
            run_url = f"{server_url.rstrip('/')}/{own_repo}/actions/runs/{run_id}"
        return (mode, repo, token, branch, remote_path, pr_number, run_url)

def _detect_pr_number(self) -> int | None:
        event_path = self.env.get("GITHUB_EVENT_PATH", "").strip()
        if not event_path:
            return None
        try:
            payload = json.loads(Path(event_path).read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return None
        for key in ("pull_request", "issue"):
            nested = payload.get(key)
            if isinstance(nested, dict) and isinstance(nested.get("number"), int):
                return nested["number"]
        return None

def _ensure_branch(self, api_base: str, repo: str, token: str, branch: str) -> bool:
        """Creates the publish branch from GITHUB_SHA if it does not exist yet."""
        ref_path = quote(f"heads/{branch}", safe="")
        status, _ = self._api("GET", f"{api_base}/repos/{repo}/git/ref/{ref_path}", token)
        if status == 200:
            return True

        base_sha: str | None = self.env.get("GITHUB_SHA", "").strip()
        if not base_sha:
            base_sha = self._default_branch_sha(api_base, repo, token)
        if not base_sha:
            return False

        status, _ = self._api(
            "POST",
            f"{api_base}/repos/{repo}/git/refs",
            token,
            {"ref": f"refs/heads/{branch}", "sha": base_sha},
        )
        return status in (200, 201)

def _default_branch_sha(self, api_base: str, repo: str, token: str) -> str | None:
        status, repo_data = self._api("GET", f"{api_base}/repos/{repo}", token)
        default_branch = (
            repo_data.get("default_branch", "main") if isinstance(repo_data, dict) else "main"
        )
        status, ref_data = self._api(
            "GET", f"{api_base}/repos/{repo}/git/ref/heads/{default_branch}", token
        )
        if status == 200 and isinstance(ref_data, dict):
            obj = ref_data.get("object")
            if isinstance(obj, dict):
                return obj.get("sha")
        return None

def _put_file(
        self, api_base: str, repo: str, token: str, branch: str, path: str, payload: bytes
    ) -> bool:
        url = f"{api_base}/repos/{repo}/contents/{path}"
        body: dict[str, Any] = {
            "message": f"ci: publish ici verification report {path}",
            "content": base64.b64encode(payload).decode("ascii"),
            "branch": branch,
        }
        for attempt in range(3):
            sha = self._get_file_sha(api_base, repo, token, branch, path)
            if sha:
                body["sha"] = sha
            status, _ = self._api("PUT", url, token, body)
            if status in (200, 201):
                return True
            if status != 409:
                return False
            time.sleep(0.5 * (attempt + 1))
        return False

def _get_file_sha(
        self, api_base: str, repo: str, token: str, branch: str, path: str
    ) -> str | None:
        url = f"{api_base}/repos/{repo}/contents/{path}?ref={branch}"
        status, data = self._api("GET", url, token)
        if status == 200 and isinstance(data, dict):
            return data.get("sha")
        return None

def _check_pages(self, api_base: str, repo: str, token: str) -> tuple[bool, str | None]:
        status, data = self._api("GET", f"{api_base}/repos/{repo}/pages", token)
        if status == 200 and isinstance(data, dict):
            return True, data.get("html_url")
        return False, None

def _find_existing_comment(
        self, api_base: str, repo: str, token: str, pr_number: int
    ) -> int | None:
        """Paginates through issue comments looking for the sticky marker.

        GitHub's default page size is 30; a PR with more comments than that
        would otherwise never find its own prior sticky comment and would
        keep posting duplicates on every run instead of updating in place.
        """
        for page in range(1, 21):  # 20 pages * 100 = 2000 comments, a generous cap
            url = f"{api_base}/repos/{repo}/issues/{pr_number}/comments?per_page=100&page={page}"
            status, comments = self._api("GET", url, token)
            if status != 200 or not isinstance(comments, list) or not comments:
                return None
            for comment in comments:
                if isinstance(comment, dict) and PUBLISH_MARKER in (comment.get("body") or ""):
                    return comment.get("id")
            if len(comments) < 100:
                return None
        return None

def _upsert_comment(
        self, api_base: str, repo: str, token: str, pr_number: int, body: str
    ) -> str | None:
        if not repo or not token:
            return None
        existing_id = self._find_existing_comment(api_base, repo, token, pr_number)

        if existing_id:
            status, data = self._api(
                "PATCH",
                f"{api_base}/repos/{repo}/issues/comments/{existing_id}",
                token,
                {"body": body},
            )
        else:
            status, data = self._api(
                "POST",
                f"{api_base}/repos/{repo}/issues/{pr_number}/comments",
                token,
                {"body": body},
            )

        if status in (200, 201) and isinstance(data, dict):
            return data.get("html_url")
        return None

def _api(
        self, method: str, url: str, token: str, payload: dict[str, Any] | None = None
    ) -> tuple[int, Any]:
        req = urllib.request.Request(url, method=method)
        req.add_header("Authorization", f"Bearer {token}")
        req.add_header("Accept", "application/vnd.github+json")
        req.add_header("X-GitHub-Api-Version", "2022-11-28")
        req.add_header("User-Agent", "ici-publish")
        data = None
        if payload is not None:
            data = json.dumps(payload).encode("utf-8")
            req.add_header("Content-Type", "application/json")
        try:
            with urllib.request.urlopen(req, data=data, timeout=30) as resp:
                raw = resp.read().decode("utf-8")
                return resp.status, json.loads(raw) if raw.strip() else None
        except urllib.error.HTTPError as err:
            raw = err.read().decode("utf-8", errors="replace")
            try:
                return err.code, json.loads(raw)
            except ValueError:
                return err.code, raw
        except OSError as err:
            # Network/DNS/TLS failure — surface it instead of silently
            # returning an empty body, so a real cause is visible if a
            # caller ever inspects it (and in worst case shows up as a
            # generic-but-present reason rather than nothing at all).
            return -1, {"error": str(err)}

def _check_file_for_leaks(rel_path: str, content: str) -> list[InspectionTarget]:
    try:
        tree = ast.parse(content, filename=rel_path)
    except SyntaxError:
        return []
    visitor = _LeakVisitor(rel_path)
    visitor.visit(tree)
    # Also check for mutable default args
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            for default in node.args.defaults + node.args.kw_defaults:
                if isinstance(default, (ast.List, ast.Dict, ast.Set)):
                    visitor.findings.append(
                        InspectionTarget(
                            file_path=rel_path,
                            start_line=getattr(node, "lineno", 1),
                            target_name="Resource:MutableDefault",
                            status=EngineStatus.WARN,
                            message=f"Mutable default argument in {node.name}()",
                        )
                    )
    return visitor.findings

def _cpp_test_sources(self) -> list[Path]:
        tests_root = self.project_root / "tests"
        if not tests_root.is_dir():
            return []
        return sorted(_iter_project_files(tests_root, self.project_root, (".cpp",)))

def _cpp_library_flags(self) -> list[str]:
        nas_cpp = get_nas_cpp_lib_dir()
        if nas_cpp.exists() and (nas_cpp / "lib").exists():
            return [f"-L{nas_cpp / 'lib'}", "-lips_core", f"-Wl,-rpath,{nas_cpp / 'lib'}"]
        return []

def _check_python_resource_warnings(
        self, tests_root: Path, targets: list[InspectionTarget]
    ) -> tuple[bool, bool]:
        python_cmd = self._resolve_python()
        command = [
            *python_cmd,
            "-W",
            "error::ResourceWarning",
            "-m",
            "pytest",
            "-o",
            "addopts=",
            "tests",
        ]
        if not tests_root.is_dir():
            message = "Python ResourceWarning check skipped: tests directory is missing"
            return self._missing_python_scope(targets, message, command, "tests")
        if not any(
            path.suffix == ".py"
            and (path.name.startswith("test_") or path.name.endswith("_test.py"))
            for path in tests_root.rglob("*")
        ):
            message = "Python ResourceWarning check skipped: no Python test files were selected"
            return self._missing_python_scope(targets, message, command, "tests")

        env = os.environ.copy()
        env["PYTHONDONTWRITEBYTECODE"] = "1"
        env["PYTEST_ADDOPTS"] = " ".join(
            part for part in (env.get("PYTEST_ADDOPTS", ""), "-p no:cacheprovider") if part
        )
        source_paths = [str(path) for path in self._source_dirs()]
        if source_paths:
            python_paths = [*source_paths, env.get("PYTHONPATH", "")]
            env["PYTHONPATH"] = os.pathsep.join(path for path in python_paths if path)
        if env.get("WSL_DISTRO_NAME") and Path("/tmp").is_dir():
            for key in ("TMPDIR", "TMP", "TEMP"):
                env[key] = "/tmp"
        try:
            result = run_process(command, cwd=self.project_root, env=env)
        except Exception as exc:
            self._record_tool_exception("pytest resource warnings", command, exc)
            self._append_scope_error(
                targets, "tests", "PythonResourceWarnings", f"Pytest could not execute: {exc}"
            )
            return False, False
        evidence = self._record_process("pytest resource warnings", command, result)
        if self._process_incomplete(result):
            message = self._incomplete_message("Pytest ResourceWarning check", result)
            evidence.error = message
            self._tool_errors.append(message)
            self._append_scope_error(targets, "tests", "PythonResourceWarnings", message)
            return False, False
        output = f"{result.stdout}\n{result.stderr}"
        if self._pytest_module_missing(output, result.returncode):
            message = f"Pytest is unavailable: {self._snippet(output)}"
            evidence.error = message
            return self._missing_python_scope(targets, message, command, "tests")
        if result.returncode == 5 or not self._pytest_has_executed_result(output):
            message = "Pytest returned success without parseable test results"
            if result.returncode == 5:
                message = "Pytest collected 0 tests"
            evidence.error = f"{message}: {self._snippet(output)}"
            return self._missing_python_scope(targets, message, command, "tests")
        if result.returncode == 0:
            self._measured_scopes += 1
            targets.append(
                InspectionTarget(
                    file_path="tests",
                    start_line=1,
                    target_name="PythonResourceWarnings",
                    status=EngineStatus.PASS,
                    message="pytest completed with ResourceWarning promoted to errors",
                )
            )
            return False, False
        if "ResourceWarning" in output:
            if not self._resource_warning_targets(output, targets):
                targets.append(
                    InspectionTarget(
                        file_path="tests",
                        start_line=1,
                        target_name="ResourceWarning",
                        status=EngineStatus.FAIL,
                        message=self._snippet(output),
                    )
                )
            self._measured_scopes += 1
            return True, False

        message = self._tool_failure_message("Pytest ResourceWarning check", result)
        evidence.error = message
        self._tool_errors.append(message)
        self._append_scope_error(targets, "tests", "PythonResourceWarnings", message)
        return False, False

def _resolve_python(self) -> list[str]:
        """Use the same configured/project-venv/system interpreter order as Task 5."""

        configured = self.get_config("test").get("python")
        if configured:
            return [str(configured)]
        candidates = (
            self.project_root / ".venv" / "bin" / "python",
            self.project_root / ".venv" / "Scripts" / "python.exe",
        )
        for candidate in candidates:
            try:
                if candidate.is_file():
                    return [str(candidate)]
            except OSError:
                continue
        return [sys.executable]

def _source_dirs(self) -> list[Path]:
        from ici.core.project import get_source_dirs

        return get_source_dirs(self.project_root, self.config)

def _normalize_output_path(self, value: str) -> str:
        path = Path(value)
        try:
            return str(path.relative_to(self.project_root))
        except ValueError:
            return value

def _pytest_module_missing(output: str, returncode: int) -> bool:
        return returncode != 0 and bool(
            re.search(r"No module named ['\"]pytest['\"]|No module named pytest", output)
        )

def _contains_sanitizer_diagnostic(output: str) -> bool:
        return bool(
            _SANITIZER_ERROR_RE.search(output)
            or _SANITIZER_SUMMARY_RE.search(output)
            or _UBSAN_RUNTIME_RE.search(output)
        )

def _process_incomplete(result: ProcessResult, *, allow_signal: bool = False) -> bool:
        return bool(
            result.timed_out
            or result.truncated
            or not isinstance(result.returncode, int)
            or (result.returncode < 0 and not allow_signal)
        )

def _record_tool_missing(self, name: str, message: str) -> None:
        self._tool_evidence.append(ToolEvidence(name=name, path="", error=message))
        self._tool_errors.append(message)

def _record_tool_exception(self, name: str, command: list[str], exc: Exception) -> None:
        message = f"{type(exc).__name__}: {exc}"
        if any(
            evidence.name == name and evidence.argv == command and evidence.error == message
            for evidence in self._tool_evidence
        ):
            return
        self._tool_evidence.append(
            ToolEvidence(name=name, path=command[0], argv=command, error=message)
        )
        self._tool_errors.append(message)

def _append_error_target(
        self, targets: list[InspectionTarget], source: Path, name: str, message: str
    ) -> None:
        self._append_scope_error(targets, str(source.relative_to(self.project_root)), name, message)

def _append_scope_error(
        targets: list[InspectionTarget], file_path: str, name: str, message: str
    ) -> None:
        targets.append(
            InspectionTarget(
                file_path=file_path,
                start_line=1,
                target_name=name,
                status=EngineStatus.ERROR,
                message=message,
            )
        )

def _issue_count(targets: list[InspectionTarget]) -> int:
        return sum(
            1 for target in targets if target.status in (EngineStatus.WARN, EngineStatus.FAIL)
        )

def _incomplete_message(self, label: str, result: ProcessResult) -> str:
        if result.timed_out:
            return f"{label} timed out: {self._snippet(result.stderr or result.stdout)}"
        if result.truncated:
            return f"{label} output was truncated: {self._snippet(result.stderr or result.stdout)}"
        return f"{label} terminated before producing a result: {self._snippet(result.stderr or result.stdout)}"

def _mask_secret_assignment(match: re.Match[str]) -> str:
    return (
        f"{match.group('key')}{match.group('op')}{match.group('quote')}"
        f"{_REDACTED}{match.group('quote')}"
    )

def _test_python_files(self) -> list[Path]:
        """Yields Python files under the conventional top-level ``tests/`` dir.

        ``get_all_python_sources`` only walks ``project.source_dirs``, which
        never includes ``tests/`` — so ``scan_tests`` needs its own explicit
        walk to actually have an effect.
        """
        tests_dir = self.project_root / "tests"
        if not tests_dir.is_dir():
            return []
        return list(_iter_project_files(tests_dir, self.project_root, (".py",)))

def _apply_coverage_policy(self, cfg: dict[str, Any]) -> tuple[bool, bool]:
        missing = self._coverage_failure_messages()
        required = bool(cfg.get("coverage_required", False)) and bool(missing)
        optional = bool(missing) and not required
        if required:
            for message in missing:
                self._record_tool_error(message)
        return required, optional

def _has_threshold_warning(
        cfg: dict[str, Any],
        optional: bool,
        has_failure: bool,
        tem: float,
        branch: float,
        func: float,
    ) -> bool:
        if optional or has_failure:
            return optional
        return (
            tem < cfg.get("min_tem_score", 4.0)
            or branch < cfg.get("min_branch_cov", 80.0)
            or func < cfg.get("min_func_cov", 90.0)
        )

def _build_test_suites(targets: list[InspectionTarget]) -> list[dict]:
        suite_map: dict[str, dict] = {}
        for target in targets:
            if target.target_name.startswith("Coverage:"):
                continue
            suite = suite_map.setdefault(
                target.file_path,
                {"file": target.file_path, "passed": 0, "failed": 0, "total": 0, "tests": []},
            )
            suite["total"] += 1
            key = "passed" if target.status == EngineStatus.PASS else "failed"
            suite[key] += 1
            suite["tests"].append(
                {
                    "name": target.target_name,
                    "status": target.status.value,
                    "message": target.message,
                }
            )
        return list(suite_map.values())

def _result_status(
        self,
        cfg: dict[str, Any],
        has_failure: bool,
        has_warn: bool,
        optional: bool,
        required: bool,
    ) -> EngineStatus:
        if self._tool_errors or required:
            return EngineStatus.ERROR
        if optional and not has_failure:
            return EngineStatus.WARN
        return self.evaluate_status(has_failure, has_warn, cfg.get("mode", "pass_fail"))

def _result_summary(
        self,
        passed_tests: int,
        total_tests: int,
        func_cov: float,
        tem_score: float,
        tem_info: dict[str, Any],
        optional: bool,
    ) -> str:
        if self._tool_errors:
            return "; ".join(self._tool_errors[:3])
        summary = (
            f"{passed_tests}/{total_tests} Tests Passed | "
            f"{tem_info['cov_label']}: {tem_info['cov_shown']:.1f}%{tem_info['cov_suffix']}, "
            f"Func: {func_cov:.1f}% -> TEM: {tem_score:.2f} / 5.0"
        )
        if optional:
            summary += "; Coverage evidence ESTIMATED (optional; not threshold evidence)"
        return summary

def _result_evidence(self, optional: bool, required: bool) -> EvidenceState:
        if self._tool_errors or required:
            return EvidenceState.NOT_RUN
        return EvidenceState.ESTIMATED if optional else EvidenceState.MEASURED

def _mark_zero_tests(
        self, language: str, targets: list[InspectionTarget]
    ) -> tuple[int, int, bool]:
        targets.append(
            InspectionTarget(
                file_path="tests",
                start_line=1,
                target_name=f"[{language}] Tests",
                status=EngineStatus.FAIL,
                message="No tests collected",
            )
        )
        return 0, 0, True

def _coverage_failure_messages(self) -> list[str]:
        failures = list(self._coverage_errors)
        if not self._python_test_attempted and not self._cpp_test_attempted:
            failures.append("No project sources or tests were available")
        if self._python_test_attempted and not self._coverage_data:
            failures.append("Python coverage evidence was unavailable or malformed")
        if self._cpp_test_attempted and not self._cpp_coverage_rows:
            failures.append("C++ gcov coverage evidence was unavailable or malformed")
        return list(dict.fromkeys(failures))

def _record_tool(self, name: str, argv: list[str], result) -> None:
        self._tool_evidence.append(
            ToolEvidence(name=name, path=argv[0], argv=argv, returncode=result.returncode)
        )

def _record_tool_error(self, message: str) -> None:
        if message not in self._tool_errors:
            self._tool_errors.append(message)

def _calc_tem(
        self, branch_cov: float, func_cov: float, passed_tests: int, total_tests: int
    ) -> dict[str, Any]:
        return calculate_tem(branch_cov, func_cov, passed_tests, total_tests, self._coverage_totals)

def _run_python_tests(self, targets: list[InspectionTarget]) -> tuple[int, int, bool]:
        python_cmd = self._resolve_python()
        pytest_cmd = [*python_cmd, "-m", "pytest"]
        env = self._build_python_test_env()
        coverage_result = self._run_coverage_tests(python_cmd, env, targets)
        if coverage_result is not None:
            return coverage_result
        pytest_result = self._run_plain_pytest(pytest_cmd, env, targets)
        if pytest_result is not None:
            return pytest_result
        return self._run_unittest(env, targets, python_cmd)

def _generate_coverage_json(
        self, cov_cmd: list[str], cov_dir: Path, cov_env: dict[str, str]
    ) -> None:
        json_path = cov_dir / "coverage.json"
        with contextlib.suppress(OSError):
            json_path.unlink()
        command = [*cov_cmd, "json", "-o", str(json_path)]
        result = run_process(command, cwd=self.project_root, env=cov_env)
        self._record_tool("coverage json", command, result)
        self._coverage_data = None
        self._coverage_measured = False
        if result.timed_out:
            self._record_tool_error("Coverage JSON generation timed out")
        elif result.truncated:
            self._record_tool_error("Coverage JSON output was truncated")
        elif result.returncode == -1:
            self._record_tool_error("Coverage JSON executable was unavailable")
        elif result.returncode != 0:
            self._record_tool_error(
                f"Coverage JSON generation failed with exit code {result.returncode}"
            )
        else:
            expected_files = {
                str(path.relative_to(self.project_root))
                for path in get_all_python_sources(self.project_root, self.config)
            }
            self._coverage_data = self._parse_coverage_json(json_path, expected_files)
            if self._coverage_data is None:
                self._coverage_errors.append("Python coverage JSON was missing or malformed")
            else:
                self._coverage_measured = True

def _parse_pytest_result(
        self, result, targets: list[InspectionTarget]
    ) -> tuple[int, int, bool]:
        passed, total, has_failure = self._parse_pytest_stdout(
            result.stdout + ("\n" + result.stderr if result.stderr else ""), targets
        )
        output = result.stdout + "\n" + result.stderr
        collected = re.search(r"\bcollected\s+(\d+)\s+items?\b", output)
        if total == 0 and collected is not None:
            total = int(collected.group(1))
        if result.returncode == 5 or (total == 0 and result.returncode == 0):
            has_failure = True
            if not any(t.target_name == "[Python] Tests" for t in targets):
                targets.append(
                    InspectionTarget(
                        file_path="tests",
                        start_line=1,
                        target_name="[Python] Tests",
                        status=EngineStatus.FAIL,
                        message="No tests collected",
                    )
                )
        elif result.returncode == 0 and not pytest_result_has_evidence(output):
            self._record_tool_error("Pytest returned success without parseable test results")
        elif result.returncode not in (0, 1):
            self._record_tool_error(f"Pytest failed with exit code {result.returncode}")
        elif result.returncode == 1 and not has_failure:
            self._record_tool_error("Pytest returned failure without parseable diagnostics")
        elif total == 0:
            has_failure = True
        return passed, total, has_failure

def _parse_coverage_json(
        self, json_path: Path, expected_files: set[str] | None = None
    ) -> dict | None:
        return parse_coverage_json(json_path, self.project_root, expected_files)

def _collect_cpp_coverage(self, gcov_bin: str, build_tmp: Path, source_files: set[str]) -> None:
        gcno_files = sorted(str(p) for p in build_tmp.glob("*.gcno"))
        if gcno_files:
            gcov_cmd = [gcov_bin, "-b", "-p", "-o", ".", *gcno_files]
            gcov_result = run_process(gcov_cmd, cwd=build_tmp)
            self._record_tool("gcov", gcov_cmd, gcov_result)
            if gcov_result.timed_out or gcov_result.truncated:
                self._record_tool_error("gcov output was incomplete")
            elif gcov_result.returncode != 0:
                self._record_tool_error(f"gcov failed with exit code {gcov_result.returncode}")
        else:
            self._coverage_errors.append("C++ gcov data files were unavailable")
        self._cpp_coverage_rows = self._parse_gcov_dir(build_tmp, source_files)
        self._cpp_function_rows = self._parse_gcov_functions(build_tmp, source_files)
        if not self._cpp_coverage_rows:
            self._coverage_errors.append("C++ gcov coverage output was missing or malformed")
        else:
            self._coverage_measured = True

def _measure_coverage(
        self, proj_type: str, has_test_failures: bool
    ) -> tuple[float, float, list[InspectionTarget]]:
        """Calculates branch coverage, function coverage, and per-module coverage rows."""
        missed_targets: list[InspectionTarget] = []
        py_sources = get_all_python_sources(self.project_root, self.config)
        cpp_sources = get_all_cpp_sources(self.project_root, self.config)

        cov_data = self._coverage_data
        self._build_coverage_summary()

        py_func_rows = self._compute_python_function_coverage(cov_data) if cov_data else []
        cpp_func_rows = getattr(self, "_cpp_function_rows", [])
        self._function_rows = [*py_func_rows, *cpp_func_rows]

        total_lines = 0
        for p in py_sources + cpp_sources:
            try:
                with open(p, encoding="utf-8", errors="ignore") as f:
                    total_lines += sum(
                        1
                        for line in f
                        if line.strip() and not line.strip().startswith(("#", "//", "/*"))
                    )
            except (OSError, UnicodeDecodeError) as err:
                _ = err

        if total_lines == 0:
            return 100.0, 100.0, []

        if has_test_failures:
            branch_cov = 45.0
            func_cov = 50.0
        else:
            branch_cov = 85.0
            func_cov = 95.0

        if self._function_rows:
            covered_funcs = sum(1 for r in self._function_rows if r["covered"])
            func_cov = covered_funcs / len(self._function_rows) * 100.0

        totals = self._coverage_totals
        if totals and totals.get("branch_cover") is not None:
            branch_cov = totals["branch_cover"]
        elif cov_data and cov_data.get("branch_cov") is not None:
            branch_cov = cov_data["branch_cov"]

        for row in self._coverage_files:
            if row["stmts"] >= 5 and row["cover"] < 80.0:
                missed_targets.append(
                    InspectionTarget(
                        file_path=row["file"],
                        start_line=1,
                        target_name="Coverage:Module",
                        status=EngineStatus.WARN,
                        message=(
                            f"Module coverage {row['cover']:.1f}% — {row['miss']} missed statements"
                        ),
                        metrics={"coverage": row["cover"]},
                    )
                )

        return branch_cov, func_cov, missed_targets

def _resolve_python(self) -> list[str]:
        """Resolve the interpreter used for every Python test-related module."""

        configured = self.get_config("test").get("python")  # type: ignore[attr-defined]
        if configured:
            return [str(configured)]

        candidates = (
            self.project_root / ".venv" / "bin" / "python",  # type: ignore[attr-defined]
            self.project_root / ".venv" / "Scripts" / "python.exe",  # type: ignore[attr-defined]
        )
        for candidate in candidates:
            try:
                if candidate.is_file():
                    return [str(candidate)]
            except OSError:
                continue
        return [sys.executable]

def _build_python_test_env(self) -> dict[str, str]:
        env = os.environ.copy()
        source_paths = [str(d) for d in get_source_dirs(self.project_root, self.config)]  # type: ignore[attr-defined]
        if source_paths:
            env["PYTHONPATH"] = ":".join([*source_paths, env.get("PYTHONPATH", "")])
        if env.get("WSL_DISTRO_NAME") and Path("/tmp").is_dir():
            for key in ("TMPDIR", "TMP", "TEMP"):
                env[key] = "/tmp"
        return env

def _interpreter_from_command(self, command: list[str] | None) -> list[str]:
        """Normalize legacy pytest argv into its interpreter prefix."""

        if not command:
            return self._resolve_python()
        if "-m" in command:
            module_index = command.index("-m")
            if module_index > 0:
                return command[:module_index]
        executable = command[0]
        if executable.endswith("pytest"):
            parent = Path(executable).parent
            for name in ("python", "python.exe"):
                candidate = parent / name
                if candidate.exists() or name == "python":
                    return [str(candidate)]
        return [executable]

def _check_python_types(
        self,
        targets: list[InspectionTarget],
        tool_errors: list[str] | None = None,
        tool_warnings: list[str] | None = None,
        tool_evidence: list[ToolEvidence] | None = None,
        python_sources: list[Path] | None = None,
    ) -> bool:
        errors = tool_errors if tool_errors is not None else []
        warnings = tool_warnings if tool_warnings is not None else []
        evidence = tool_evidence if tool_evidence is not None else []
        mypy_cmd = self._find_mypy_cmd()
        if mypy_cmd is not None and self._run_mypy(mypy_cmd, targets, errors, evidence):
            return True
        if mypy_cmd is None:
            evidence.append(
                ToolEvidence(
                    name="mypy",
                    path="",
                    error="tool not found; no command was executed",
                )
            )
            if self.get_config("type").get("mypy_required", False):
                errors.append("Mypy is required but was not found")
            else:
                warnings.append("Mypy is unavailable; AST fallback is ESTIMATED")
        return self._check_python_annotations(targets, python_sources)

def _find_mypy_cmd(self) -> list[str] | None:
        which_mypy = shutil.which("mypy")
        if which_mypy:
            return [which_mypy]
        venv_mypy = find_project_executable(self.project_root, "mypy")
        if venv_mypy:
            return [venv_mypy]
        return None

def _append_mypy_target(self, line: str, targets: list[InspectionTarget]) -> None:
        match = _MYPY_DIAGNOSTIC_RE.fullmatch(line.strip())
        if not match:
            return
        kind = match.group("kind")
        try:
            rel_path = self._diagnostic_path(match.group("file"))
        except (TypeError, ValueError):
            rel_path = match.group("file")
        message = match.group("message")
        if kind != "error" and _merge_note_target(targets, rel_path, message):
            return
        targets.append(
            InspectionTarget(
                file_path=rel_path,
                start_line=int(match.group("line")),
                target_name="MypyError" if kind == "error" else "MypyNote",
                status=EngineStatus.FAIL if kind == "error" else EngineStatus.WARN,
                message=message,
            )
        )

def _validated_mypy_success(output: str) -> tuple[bool, list[str]]:
        lines = output.splitlines()
        summary_indexes = [
            index for index, line in enumerate(lines) if _MYPY_SUCCESS_LINE_RE.fullmatch(line)
        ]
        if len(summary_indexes) != 1 or summary_indexes[0] != len(lines) - 1:
            return False, []

        summary = _MYPY_SUCCESS_LINE_RE.fullmatch(lines[-1])
        if summary is None:
            return False, []
        count = int(summary.group("count"))
        if count < 1:
            return False, []
        expected_noun = "file" if count == 1 else "files"
        if lines[-1] != f"Success: no issues found in {count} source {expected_noun}":
            return False, []

        diagnostics: list[str] = []
        for line in lines[:-1]:
            match = _MYPY_DIAGNOSTIC_RE.fullmatch(line)
            if match is None:
                return False, []
            diagnostics.append(line)
            if match.group("kind") != "note":
                return False, diagnostics
        return True, diagnostics

def _is_valid_mypy_success(output: str) -> bool:
        valid, _diagnostics = TypeCheckEngine._validated_mypy_success(output)
        return valid

def _record_tool_exception(
        evidence: list[ToolEvidence], command: list[str], exc: Exception
    ) -> None:
        evidence.append(
            ToolEvidence(
                name="mypy",
                path=command[0],
                argv=command,
                error=f"{type(exc).__name__}: {exc}",
            )
        )

def _diagnostic_path(self, value: str) -> str:
        path = Path(value.strip())
        try:
            return str(path.relative_to(self.project_root))
        except ValueError:
            return str(path)

def _mark_cpp_type_check_skipped(
        self, targets: list[InspectionTarget], warnings: list[str], count: int
    ) -> None:
        sources = get_all_cpp_sources(self.project_root, self.config)
        if not sources:
            targets.append(
                InspectionTarget(
                    file_path=".",
                    start_line=1,
                    target_name="C++TypeCheck",
                    status=EngineStatus.SKIP,
                    message="No applicable C++ source files were selected; type checking was not run",
                )
            )
        for source in sources:
            targets.append(
                InspectionTarget(
                    file_path=str(source.relative_to(self.project_root)),
                    start_line=1,
                    target_name="C++TypeCheck",
                    status=EngineStatus.SKIP,
                    message="C++ type checking is not implemented; source was not type-checked",
                )
            )
        warnings.append(
            f"C++ type checking is skipped for {count} source file(s); evidence is ESTIMATED"
        )

def _mark_python_type_check_skipped(
        self, targets: list[InspectionTarget], warnings: list[str]
    ) -> None:
        targets.append(
            InspectionTarget(
                file_path=".",
                start_line=1,
                target_name="Mypy",
                status=EngineStatus.SKIP,
                message="No applicable Python source files were selected; Mypy was not run",
            )
        )
        warnings.append(
            "Python type checking is skipped: no applicable Python source files; "
            "evidence is ESTIMATED"
        )

def _check_python_annotations(
        self, targets: list[InspectionTarget], python_sources: list[Path] | None = None
    ) -> bool:
        source_files = (
            python_sources
            if python_sources is not None
            else get_all_python_sources(self.project_root, self.config)
        )
        for py_file in source_files:
            try:
                content = py_file.read_text(encoding="utf-8")
                tree = ast.parse(content, filename=str(py_file))
                rel_p = str(py_file.relative_to(self.project_root))

                for node in ast.walk(tree):
                    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        if node.name.startswith("__") and node.name.endswith("__"):
                            continue
                        cfg = self.get_config("type")
                        warn_on_missing = cfg.get("warn_on_missing_annotation", False)
                        # Check return annotation
                        if node.returns is None and warn_on_missing:
                            targets.append(
                                InspectionTarget(
                                    file_path=rel_p,
                                    start_line=node.lineno,
                                    target_name=f"{node.name}()",
                                    status=EngineStatus.WARN,
                                    message=f"Function '{node.name}' is missing return type annotation",
                                )
                            )
            except (SyntaxError, OSError) as err:
                _ = err

        return False

def __init__(self, project_root: Path | None = None, config: dict[str, Any] | None = None):
        self.project_root = (project_root or Path.cwd()).resolve()
        self.config = config or load_config(self.project_root)

def format_status_badge(status: EngineStatus) -> str:
    if status == EngineStatus.PASS:
        return "[bold green] PASS [/]"
    elif status == EngineStatus.WARN:
        return "[bold yellow] WARN [/]"
    elif status == EngineStatus.FAIL:
        return "[bold red] FAIL [/]"
    elif status == EngineStatus.ERROR:
        return "[bold red] ERROR [/]"
    else:
        return "[dim] SKIP [/]"

def print_suite_dashboard(suite: VerificationSuiteResult, base_dir: Path | None = None) -> None:
    """Prints the comprehensive Rich terminal dashboard for all verification engines."""
    base = (base_dir or Path.cwd()).resolve()

    status_color = (
        "green"
        if suite.suite_status == EngineStatus.PASS
        else ("yellow" if suite.suite_status == EngineStatus.WARN else "red")
    )
    banner_text = Text(
        f"ici Unified Verification Suite — {suite.suite_status.value}", style=f"bold {status_color}"
    )
    console.print(Panel(banner_text, box=box.DOUBLE, border_style=status_color))

    table = Table(box=box.ROUNDED, header_style="bold cyan", expand=True)
    table.add_column("Engine", style="bold", width=16)
    table.add_column("Status", justify="center", width=10)
    table.add_column("Summary", style="white")
    table.add_column("Score / Metrics", justify="right", width=22)
    table.add_column("Duration", justify="right", width=10)

    for res in suite.results:
        status_badge = format_status_badge(res.status)
        score_str = format_score_display(res)
        duration_str = f"{res.duration:.2f}s" if res.duration > 0 else "-"
        table.add_row(
            escape(res.engine_name),
            status_badge,
            escape(res.summary),
            escape(score_str),
            escape(duration_str),
        )

    console.print(table)

    # Print Drill-Down for Failures, Errors, and Warnings
    issues = [
        r
        for r in suite.results
        if r.status in (EngineStatus.FAIL, EngineStatus.ERROR, EngineStatus.WARN, EngineStatus.SKIP)
    ]
    if issues:
        console.print(
            "\n[bold red]── Action Required: Violations & Issues Drill-Down ──[/bold red]"
        )
        for issue in issues:
            border = "red" if issue.status in (EngineStatus.FAIL, EngineStatus.ERROR) else "yellow"
            issue_panel_content = []

            if issue.engine_name == "dup" and "clone_groups" in issue.extra:
                for g in issue.extra["clone_groups"]:
                    occ_links = [
                        make_terminal_link(occ["file_path"], occ["start_line"], base)
                        for occ in g["occurrences"]
                    ]
                    line_hdr = (
                        f"[{border}]• [CloneGroup#{escape(str(g['id']))}][/] [bold]"
                        f"{' <-> '.join(occ_links)}[/] ({escape(str(g['lines_count']))} duplicate lines)"
                    )
                    issue_panel_content.append(line_hdr)
                    if g.get("snippet"):
                        for s_line in g["snippet"].strip().splitlines()[:4]:
                            issue_panel_content.append(
                                f"    [dim white]│[/dim white] {escape(s_line)}"
                            )
            else:
                for target in issue.targets:
                    if target.status != EngineStatus.PASS:
                        link_str = make_terminal_link(target.file_path, target.start_line, base)
                        line_hdr = f"[{border}]• [{target.status.value}][/] [bold]{link_str}[/] ({escape(target.target_name or 'issue')})"
                        issue_panel_content.append(line_hdr)
                        if target.message:
                            issue_panel_content.append(f"  [dim]{escape(target.message)}[/dim]")
                        if target.snippet:
                            snippet_lines = target.snippet.strip().splitlines()
                            for s_line in snippet_lines[:6]:
                                issue_panel_content.append(
                                    f"    [dim white]│[/dim white] {escape(s_line)}"
                                )

            if issue_panel_content:
                console.print(
                    Panel(
                        "\n".join(issue_panel_content),
                        title=f"[{border}]{escape(issue.engine_name)} Issues[/]",
                        border_style=border,
                        box=box.SQUARE,
                    )
                )

    # Print Overall Footer
    tem_str = (
        f" | TEM Score: [bold cyan]{suite.tem_score:.2f} / {suite.max_tem_score:.1f}[/bold cyan]"
        if suite.tem_score is not None
        else ""
    )
    failed_count = max(0, suite.failed_count - suite.error_count)
    summary_text = (
        f"[bold]Total Engines:[/] {suite.total_count}  "
        f"([green]Pass: {suite.passed_count}[/green], "
        f"[yellow]Warn: {suite.warned_count}[/yellow], "
        f"[red]Fail: {failed_count}[/red], "
        f"[red]Error: {suite.error_count}[/red], "
        f"[dim]Skip: {suite.skipped_count}[/dim])"
        f"{tem_str}  |  "
        f"[dim]Total Time: {suite.duration:.2f}s[/dim]"
    )
    console.print(Panel(summary_text, style="white", border_style="cyan"))

def _read_text(package: str, resource: str) -> str:
    try:
        return (_files(package) / resource).read_text(encoding="utf-8")
    except Exception:
        # Fallback to a file path relative to this file (for dev without
        # package install) -- resource lives under html/assets/, one level
        # below this file's own parent.
        return (Path(__file__).parent / "assets" / resource).read_text(encoding="utf-8")

def _render_cycle_chips(nodes: list[str], kind: str) -> str:
    """Renders a cycle chain as flex-wrapped chips with arrows."""
    chips = []
    for i, node in enumerate(nodes):
        if i > 0:
            chips.append("<span class='cycle-arrow'>→</span>")
        short = node if len(node) <= 48 else node[:45] + "…"
        chips.append(
            f"<code class='cycle-chip' title='{html.escape(node)}'>{html.escape(short)}</code>"
        )
    chips.append("<span class='cycle-arrow'>↩</span>")
    return f"<div class='cycle-chain'>{(''.join(chips))}<span class='badge' style='background:#1f293d; color:#9ca3af'>{kind}</span></div>"

def _split_scope(files_data: list[dict]) -> tuple[list[dict], list[dict]]:
    """Splits files into source-scope and whole-project sets (legacy data = source)."""
    if files_data and "scope" not in files_data[0]:
        return files_data, []
    source = [f for f in files_data if f.get("scope") == "source"]
    return source, files_data

def _get_status_theme(status: EngineStatus) -> tuple[str, str, str]:
    """Returns color, bg, and border for overall status."""
    if status == EngineStatus.PASS:
        return "#10b981", "rgba(16, 185, 129, 0.15)", "#10b981"
    if status == EngineStatus.WARN:
        return "#f59e0b", "rgba(245, 158, 11, 0.15)", "#f59e0b"
    if status == EngineStatus.SKIP:
        return "#9ca3af", "rgba(156, 163, 175, 0.15)", "#9ca3af"
    if status == EngineStatus.ERROR:
        return "#b91c1c", "rgba(185, 28, 28, 0.15)", "#b91c1c"
    return "#ef4444", "rgba(239, 68, 68, 0.15)", "#ef4444"

def _extract_suite_data(
    results: list[EngineResult],
) -> tuple[dict[str, EngineResult], list[tuple[str, InspectionTarget]], int, int, int, int, int]:
    """Extracts engine map, actionable issues list, and status counts."""
    eng_map: dict[str, EngineResult] = {}
    all_issues: list[tuple[str, Any]] = []
    p_cnt = 0
    w_cnt = 0
    f_cnt = 0
    e_cnt = 0
    s_cnt = 0

    for r in results:
        eng_map[r.engine_name] = r
        if r.status == EngineStatus.PASS:
            p_cnt += 1
        elif r.status == EngineStatus.WARN:
            w_cnt += 1
        elif r.status == EngineStatus.FAIL:
            f_cnt += 1
        elif r.status == EngineStatus.ERROR:
            e_cnt += 1
        else:
            s_cnt += 1

        issue_count = 0
        for t in r.targets:
            if t.status != EngineStatus.PASS:
                all_issues.append((r.engine_name, t))
                issue_count += 1
        if r.status in (EngineStatus.ERROR, EngineStatus.SKIP) and issue_count == 0:
            all_issues.append(
                (
                    r.engine_name,
                    InspectionTarget(
                        file_path="",
                        start_line=1,
                        status=r.status,
                        target_name="engine",
                        message=r.summary,
                    ),
                )
            )

    return eng_map, all_issues, p_cnt, w_cnt, f_cnt, e_cnt, s_cnt

def _escape_html_attr(value: object) -> str:
    """Escape an attribute and encode line breaks instead of emitting controls."""
    return html.escape(str(value), quote=True).replace("\r", "&#13;").replace("\n", "&#10;")

def _status_color(status: EngineStatus) -> str:
    return {
        EngineStatus.PASS: "#10b981",
        EngineStatus.WARN: "#f59e0b",
        EngineStatus.FAIL: "#ef4444",
        EngineStatus.ERROR: "#dc2626",
        EngineStatus.SKIP: "#9ca3af",
    }[status]

def _cov_color(pct: float | None) -> str:
    if pct is None:
        return "#6b7280"
    if pct >= 90.0:
        return "#10b981"
    if pct >= 75.0:
        return "#f59e0b"
    return "#ef4444"

def save_json_report(suite: VerificationSuiteResult, output_path: Path) -> None:
    """Serialize a verification suite to a canonical JSON v2 report."""
    _save_json(serialize_suite_result(suite), output_path)

def save_engine_json_report(result: EngineResult, output_path: Path) -> None:
    """Serialize one standalone engine result using the same v2 contract."""
    _save_json(serialize_engine_result(result), output_path)

def emit_github_actions_annotations(suite: VerificationSuiteResult) -> None:
    """Emits GitHub Actions workflow commands (::error and ::warning) for PR inline annotations."""
    if os.environ.get("GITHUB_ACTIONS") != "true":
        return

    for res in suite.results:
        for t in res.targets:
            if t.status in (EngineStatus.FAIL, EngineStatus.ERROR):
                command = "error"
            elif t.status in (EngineStatus.WARN, EngineStatus.SKIP):
                command = "warning"
            else:
                continue
            file_path = _escape_workflow_property(t.file_path)
            engine_name = _escape_workflow_data(res.engine_name)
            message = _escape_workflow_data(t.message)
            line = _escape_workflow_property(t.start_line)
            print(f"::{command} file={file_path},line={line}::[{engine_name}] {message}")

def write_github_step_summary(markdown_content: str) -> None:
    """Appends the Markdown report to $GITHUB_STEP_SUMMARY if available."""
    summary_path = os.environ.get("GITHUB_STEP_SUMMARY")
    if summary_path:
        try:
            with open(summary_path, "a", encoding="utf-8") as f:
                f.write("\n" + markdown_content + "\n")
        except OSError as err:
            _ = err

def _escape_inline(value: object) -> str:
    """Escape untrusted text used in an inline HTML/code context."""
    return _escape_html_content(value)

def _escape_table_cell(value: object) -> str:
    """Escape untrusted table content without allowing Markdown row injection."""
    return _escape_html_content(value)

def _escape_html_content(value: object, *, encode_backticks: bool = True) -> str:
    """Escape untrusted text while retaining readable HTML table/code content."""
    escaped = html.escape(str(value), quote=False)
    escaped = escaped.replace("|", "&#124;")
    escaped = escaped.replace("[", "&#91;").replace("]", "&#93;")
    if encode_backticks:
        escaped = escaped.replace(chr(96), "&#96;")
    return escaped.replace("\r\n", "<br>").replace("\r", "<br>").replace("\n", "<br>")

def _render_code(value: object) -> str:
    """Render untrusted content in a closed HTML code element."""
    return f"<code>{_escape_html_content(value, encode_backticks=False)}</code>"

def _escape_workflow_data(value: object) -> str:
    """Escape GitHub workflow command data fields."""
    return str(value).replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A")

def _escape_workflow_property(value: object) -> str:
    """Escape GitHub workflow command properties, including separators."""
    return _escape_workflow_data(value).replace(":", "%3A").replace(",", "%2C")

def _effective_config(ctx: typer.Context):
    """Return the effective policy loaded by the CLI callback."""

    obj = ctx.ensure_object(dict)
    config = obj.get("config")
    if isinstance(config, dict):
        return config
    return load_config(Path.cwd().resolve())

def _create_engine(engine_cls, config=None):
    """Construct an engine with the effective policy for the current project."""

    root = Path.cwd().resolve()
    return engine_cls(root, config if config is not None else load_config(root))

def _exit_for_safety_status(status: EngineStatus) -> None:
    code = exit_code_for_status(status)
    if code:
        raise typer.Exit(code=code)

def _save_single_report(filename: str, res: EngineResult) -> None:
    save_engine_json_report(res, Path(filename))
    console.print(f"[dim]Report saved to: {filename}[/dim]")

def _print_engine_result(res: EngineResult) -> None:
    """Render one engine result with a status-aware icon and escaped summary."""
    style, icon = {
        EngineStatus.PASS: ("bold green", "✔"),
        EngineStatus.WARN: ("bold yellow", "⚠"),
        EngineStatus.FAIL: ("bold red", "✘"),
        EngineStatus.ERROR: ("bold red", "✘"),
        EngineStatus.SKIP: ("dim", "↷"),
    }[res.status]
    console.print(f"[{style}]{icon}[/] {escape(res.summary)}")

def _open_in_browser(html_path: str) -> None:
    path_obj = Path(html_path).resolve()
    for opener in ("wslview", "xdg-open", "open"):
        if shutil.which(opener):
            subprocess.run([opener, str(path_obj)], capture_output=True)
            return

def _resolve_filesystem_path(path: Path, description: str) -> Path:
    """Canonicalize a filesystem path and normalize resolution failures."""

    try:
        return path.resolve(strict=False)
    except (OSError, RuntimeError, TypeError, ValueError) as err:
        raise ConfigError(f"could not resolve {description} path {path}: {err}") from err

def _config_paths(base: Path, explicit_path: Path | None = None) -> list[Path]:
    """Return policy files in their fixed precedence order."""

    paths = [
        _resolve_filesystem_path(get_global_config_path(), "global configuration"),
        _resolve_filesystem_path(base / "ici.toml", "project configuration"),
        _resolve_filesystem_path(base / "dev.toml", "development configuration"),
    ]
    if explicit_path is None:
        explicit = os.environ.get("ICI_CONFIG")
        if explicit:
            explicit_path = _resolve_filesystem_path(
                Path(explicit).expanduser(), "explicit configuration"
            )
    if explicit_path is not None:
        paths.append(explicit_path)
    return paths

def _ensure_global_default_config(config: dict[str, Any]) -> None:
    """Creates the per-user global ici.toml from the default policy on first run."""
    target = get_global_config_path()
    try:
        if target.exists():
            return
        target.parent.mkdir(parents=True, exist_ok=True)
        save_config(config, target)
        print(f"[ici] 기본 전역 설정을 생성했습니다: {target}", file=sys.stderr)
    except RuntimeError as err:
        raise ConfigError(f"could not resolve global configuration path {target}: {err}") from err
    except OSError as err:
        _ = err

def _deep_merge(base: dict[str, Any], override: dict[str, Any]) -> None:
    for k, v in override.items():
        if k in base and isinstance(base[k], dict) and isinstance(v, dict):
            _deep_merge(base[k], v)
        else:
            base[k] = v

def _reject_unknown(table: dict[str, Any], allowed: set[str] | frozenset[str], path: str) -> None:
    for key in table:
        if key not in allowed:
            raise _error(f"{path}.{key}" if path else str(key), "is an unknown configuration key")

def _require_bool(value: Any, path: str) -> None:
    if not isinstance(value, bool):
        raise _error(path, "must be a boolean")

def _require_string(value: Any, path: str, *, non_empty: bool = False) -> None:
    if not isinstance(value, str) or (non_empty and not value.strip()):
        suffix = " non-empty" if non_empty else ""
        raise _error(path, f"must be a{suffix} string")

def _require_int(value: Any, path: str, *, minimum: int | None = None) -> None:
    if not isinstance(value, int) or isinstance(value, bool):
        raise _error(path, "must be an integer")
    if minimum is not None and value < minimum:
        raise _error(path, f"must be greater than or equal to {minimum}")

def _require_number(
    value: Any,
    path: str,
    *,
    minimum: float | None = None,
    maximum: float | None = None,
) -> None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise _error(path, "must be a number")
    try:
        numeric_value = float(value)
    except (OverflowError, TypeError, ValueError) as err:
        raise _error(path, "must be a finite number") from err
    if not math.isfinite(numeric_value):
        raise _error(path, "must be finite")
    if minimum is not None and numeric_value < minimum:
        raise _error(path, f"must be greater than or equal to {minimum:g}")
    if maximum is not None and numeric_value > maximum:
        raise _error(path, f"must be less than or equal to {maximum:g}")

def _require_string_list(value: Any, path: str) -> None:
    if not isinstance(value, list) or any(not isinstance(item, str) or not item for item in value):
        raise _error(path, "must be a list of non-empty strings")

def _validate_mode(table: dict[str, Any], path: str) -> None:
    if "mode" not in table:
        return
    mode = table["mode"]
    _require_string(mode, f"{path}.mode", non_empty=True)
    if mode not in MODES:
        allowed = ", ".join(sorted(MODES))
        raise _error(f"{path}.mode", f"must be one of: {allowed}")

def _validate_common_engine(table: dict[str, Any], path: str) -> None:
    if "enabled" in table:
        _require_bool(table["enabled"], f"{path}.enabled")
    if "required" in table:
        _require_bool(table["required"], f"{path}.required")
    _validate_mode(table, path)

def _validate_line(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    if "warn_limit" in table:
        _require_int(table["warn_limit"], f"{path}.warn_limit", minimum=1)
    if "fail_limit" in table:
        _require_int(table["fail_limit"], f"{path}.fail_limit", minimum=1)
    if "gate_dirs" in table:
        _require_string_list(table["gate_dirs"], f"{path}.gate_dirs")
    if "include_dirs" in table:
        _require_string_list(table["include_dirs"], f"{path}.include_dirs")
    if "exclude_dirs" in table:
        _require_string_list(table["exclude_dirs"], f"{path}.exclude_dirs")

    warn_limit = table.get("warn_limit", 500)
    fail_limit = table.get("fail_limit", 1000)
    if fail_limit < warn_limit:
        raise _error(
            f"{path}.warn_limit",
            "must be less than or equal to engines.line.fail_limit",
        )

def _validate_test(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    if "coverage_required" in table:
        _require_bool(table["coverage_required"], f"{path}.coverage_required")
    if "python" in table:
        _require_string(table["python"], f"{path}.python", non_empty=True)
    if "min_tem_score" in table:
        _require_number(table["min_tem_score"], f"{path}.min_tem_score", minimum=0, maximum=5)
    if "min_branch_cov" in table:
        _require_number(table["min_branch_cov"], f"{path}.min_branch_cov", minimum=0, maximum=100)
    if "min_func_cov" in table:
        _require_number(table["min_func_cov"], f"{path}.min_func_cov", minimum=0, maximum=100)

def _validate_type(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    for key in ("fail_on_error", "warn_on_missing_annotation", "mypy_required"):
        if key in table:
            _require_bool(table[key], f"{path}.{key}")

def _validate_lint(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    if "ruff_required" in table:
        _require_bool(table["ruff_required"], f"{path}.ruff_required")

def _validate_complexity(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    for key in ("warn_cc", "fail_cc", "warn_nesting"):
        if key in table:
            _require_int(table[key], f"{path}.{key}", minimum=1)
    warn_cc = table.get("warn_cc", 15)
    fail_cc = table.get("fail_cc", 25)
    if fail_cc < warn_cc:
        raise _error(f"{path}.warn_cc", "must be less than or equal to engines.complexity.fail_cc")

def _validate_dup(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    for key in ("warn_pct", "fail_pct"):
        if key in table:
            _require_number(table[key], f"{path}.{key}", minimum=0, maximum=100)
    if "min_window" in table:
        _require_int(table["min_window"], f"{path}.min_window", minimum=1)
    warn_pct = table.get("warn_pct", 5.0)
    fail_pct = table.get("fail_pct", 15.0)
    if fail_pct < warn_pct:
        raise _error(f"{path}.warn_pct", "must be less than or equal to engines.dup.fail_pct")

def _validate_build(table: Any) -> None:
    path = "build"
    if not isinstance(table, dict):
        raise _error(path, "must be a table")
    _reject_unknown(table, _BUILD_KEYS, path)
    if "python" not in table:
        return
    python = table["python"]
    if not isinstance(python, dict):
        raise _error("build.python", "must be a table")
    _reject_unknown(python, _BUILD_PYTHON_KEYS, "build.python")
    if "entrypoint" in python:
        _require_string(python["entrypoint"], "build.python.entrypoint", non_empty=True)

def _validate_doctor(table: Any) -> None:
    path = "doctor"
    if not isinstance(table, dict):
        raise _error(path, "must be a table")
    _reject_unknown(table, _DOCTOR_KEYS, path)
    if "required_tools" in table:
        _require_string_list(table["required_tools"], f"{path}.required_tools")

def _validate_security(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    if "scan_tests" in table:
        _require_bool(table["scan_tests"], f"{path}.scan_tests")

def _validate_cognitive(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    for key in ("warn", "fail", "warn_nesting"):
        if key in table:
            _require_int(table[key], f"{path}.{key}", minimum=1)
    # Matches CognitiveEngine's own fallback and DEFAULT_CONFIG's shipped
    # policy (warn=30, fail=60) — kept in sync deliberately.
    w = table.get("warn", 30)
    f = table.get("fail", 60)
    if f < w:
        raise _error(f"{path}.warn", "must be <= fail")

def _validate_cycle(table: dict[str, Any], path: str) -> None:
    _validate_common_engine(table, path)
    if "max_reported" in table:
        _require_int(table["max_reported"], f"{path}.max_reported", minimum=1)

def _validate_metadata(table: Any, path: str) -> None:
    if not isinstance(table, dict):
        raise _error(path, "must be a table")
    allowed = _ICI_KEYS if path == "ici" else _PROJECT_KEYS
    _reject_unknown(table, allowed, path)
    for key, value in table.items():
        if path == "project" and key == "source_dirs":
            _require_string_list(value, "project.source_dirs")
        elif key == "type":
            _require_string(value, f"{path}.{key}", non_empty=True)
            if value not in PROJECT_TYPES:
                raise _error(f"{path}.{key}", "must be one of: cpp, hybrid, python")
        else:
            _require_string(value, f"{path}.{key}", non_empty=True)

def _validate_path_list(value: Any, setting: str, base: Path) -> None:
    """Validate and canonicalize a list of project-relative path settings."""

    if not isinstance(value, list):
        raise _error(setting, "must be a list of non-empty strings")
    for index, item in enumerate(value):
        item_path = f"{setting}[{index}]"
        if not isinstance(item, str) or not item:
            raise _error(item_path, "must be a non-empty string")
        try:
            resolve_project_path(base, item)
        except ConfigError as err:
            raise ConfigError(f"{item_path}: {err}") from err

def _get_py_ver(py_path: str) -> str | None:
    try:
        res = subprocess.run(
            [
                py_path,
                "-c",
                "import sys; print(f'{sys.version_info[0]}.{sys.version_info[1]}.{sys.version_info[2]}')",
            ],
            capture_output=True,
            text=True,
            timeout=2,
        )
        if res.returncode == 0:
            return res.stdout.strip()
    except (OSError, subprocess.SubprocessError) as err:
        _ = err
    return None

def _resolve_project_root(base: Path) -> Path:
    try:
        return Path(base).resolve(strict=False)
    except (OSError, RuntimeError, TypeError, ValueError) as err:
        raise ValueError(f"could not resolve project root {base}: {err}") from err

def _safe_project_file(base: Path, name: str) -> Path | None:
    """Return an existing in-project file without following an escaped link."""
    try:
        candidate = resolve_project_path(base, name)
        return candidate if candidate.is_file() else None
    except (OSError, ValueError):
        return None

def _safe_project_dir(base: Path, path: Path) -> Path | None:
    """Return an existing in-project directory without following an escaped link."""
    try:
        candidate = resolve_project_path(base, os.fspath(path))
        return candidate if candidate.is_dir() else None
    except (OSError, ValueError):
        return None

def _iter_project_files(root: Path, base: Path, suffixes: tuple[str, ...]) -> Iterator[Path]:
    """Yield contained regular files while ignoring symlink traversal."""
    safe_root = _safe_project_dir(base, root)
    if safe_root is None:
        return

    for current, dir_names, file_names in os.walk(safe_root, topdown=True, followlinks=False):
        current_path = Path(current)
        safe_names: list[str] = []
        for dir_name in dir_names:
            path = current_path / dir_name
            if path.is_symlink():
                continue
            safe_dir = _safe_project_dir(base, path)
            if safe_dir is None or _should_ignore_path(safe_dir):
                continue
            safe_names.append(dir_name)
        dir_names[:] = safe_names

        for file_name in file_names:
            path = current_path / file_name
            if path.is_symlink() or path.suffix not in suffixes:
                continue
            try:
                canonical = resolve_project_path(base, os.fspath(path))
                if canonical.is_file() and not _should_ignore_path(canonical):
                    yield canonical
            except (OSError, ValueError):
                continue

def _validate_project_name(value: Any) -> str:
    if (
        not isinstance(value, str)
        or value in {".", ".."}
        or _PROJECT_VALUE_PATTERN.fullmatch(value) is None
    ):
        raise ValueError(f"invalid project name: {value!r}")
    return value

def _validate_project_version(value: Any) -> str:
    if not isinstance(value, str):
        raise ValueError(f"invalid project version: {value!r}")
    normalized = value[1:] if value.startswith("v") else value
    if _PROJECT_VALUE_PATTERN.fullmatch(normalized) is None:
        raise ValueError(f"invalid project version: {value!r}")
    return f"v{normalized}"

def _metadata_path(base: Path, name: str) -> Path | None:
    """Resolve one project metadata file, rejecting an escaped symlink."""
    candidate = resolve_project_path(base, name)
    try:
        if not candidate.exists():
            return None
        if not candidate.is_file():
            raise ValueError(f"project metadata path is not a file: {name}")
    except OSError as err:
        raise ValueError(f"could not inspect project metadata {name}: {err}") from err
    return candidate

def _read_toml(path: Path) -> dict[str, Any]:
    """Read one canonical TOML metadata file."""
    try:
        with path.open("rb") as stream:
            try:
                document = tomli.load(stream)
            except (ValueError, RecursionError, UnicodeError) as err:
                raise ValueError(f"could not parse project metadata {path.name}: {err}") from err
    except OSError as err:
        raise ValueError(f"could not read project metadata {path.name}: {err}") from err
    if not isinstance(document, dict):
        raise ValueError(f"project metadata must be a table: {path.name}")
    return document

def _metadata_table(document: dict[str, Any], path_name: str) -> dict[str, Any]:
    if path_name == "pyproject.toml":
        project = document.get("project", {})
        if not isinstance(project, dict):
            raise ValueError("project metadata [project] must be a table")
        return project
    return document

def _git_project_version(base: Path) -> str:
    try:
        result = subprocess.run(
            ["git", "describe", "--tags", "--always"],
            capture_output=True,
            text=True,
            cwd=base,
            timeout=2,
        )
    except (OSError, subprocess.SubprocessError):
        return "v1.0.0"
    if result.returncode == 0 and result.stdout.strip():
        return _validate_project_version(result.stdout.strip())
    return "v1.0.0"

def _should_ignore_path(p: Path) -> bool:
    parts = p.parts
    return any(
        part in (".venv", "venv", "build", "__pycache__", ".git", ".pytest_cache", ".ruff_cache")
        or part.startswith("v1.")
        or part.startswith("v0.")
        for part in parts
    )

def _limit(text: str, maximum: int) -> tuple[str, bool]:
    """Limit captured output to ``maximum`` characters."""

    if len(text) <= maximum:
        return text, False
    return text[:maximum], True

def _decode_output(value: bytes | str | None) -> str:
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    return value or ""

def _drain_stream(stream, capture: _BoundedCapture) -> None:
    try:
        while True:
            chunk = stream.read(65536)
            if not chunk:
                return
            if isinstance(chunk, str):
                chunk = chunk.encode("utf-8", errors="replace")
            capture.append(chunk)
    except (OSError, ValueError):
        return
    finally:
        with suppress(OSError, ValueError):
            stream.close()

def _write_input(stream, input_bytes: bytes) -> None:
    try:
        stream.write(input_bytes)
        stream.close()
    except (BrokenPipeError, OSError, ValueError):
        return

def _start_input_writer(
    proc: subprocess.Popen[bytes], input_text: str | None
) -> threading.Thread | None:
    if input_text is None or proc.stdin is None:
        return None
    input_thread = threading.Thread(
        target=_write_input,
        args=(proc.stdin, input_text.encode("utf-8")),
        name="ici-process-stdin",
        daemon=True,
    )
    input_thread.start()
    return input_thread

def _close_windows_job(proc) -> None:
    job_handle = getattr(proc, "_ici_job_handle", None)
    kernel32 = getattr(proc, "_ici_job_kernel32", None)
    if job_handle and kernel32 is not None:
        with suppress(OSError):
            kernel32.CloseHandle(job_handle)
    for attr in ("_ici_job_handle", "_ici_job_kernel32"):
        with suppress(AttributeError):
            delattr(proc, attr)

def _wait_after_startup_failure(proc) -> None:
    try:
        proc.wait(timeout=1.0)
    except TypeError:
        try:
            proc.wait()
        except OSError as error:
            _log_cleanup_failure("waiting for startup failure", error)
    except (OSError, subprocess.TimeoutExpired) as error:
        _log_cleanup_failure("waiting for startup failure", error)

def _remaining(deadline: float | None) -> float | None:
    if deadline is None:
        return None
    return max(0.0, deadline - time.monotonic())

def _wait_process(proc, deadline: float | None = None) -> None:
    remaining = _remaining(deadline)
    if remaining is not None and remaining <= 0:
        return
    try:
        proc.wait(timeout=remaining) if remaining is not None else proc.wait()
    except TypeError:
        # Small fakes used by the platform orchestration tests expose wait()
        # without subprocess' optional timeout parameter.
        if remaining is None:
            with suppress(OSError):
                proc.wait()
    except (OSError, subprocess.TimeoutExpired):
        return

def _terminate_process(proc: subprocess.Popen[bytes], deadline: float | None = None) -> None:
    """Terminate a process and its POSIX process group when possible."""

    if os.name == "posix":
        try:
            os.killpg(proc.pid, signal.SIGTERM)
        except ProcessLookupError as error:
            _log_cleanup_failure("SIGTERM process-group cleanup", error)
        except OSError:
            proc.terminate()

        grace = _remaining(deadline)
        grace = 0.2 if grace is None else min(grace, 0.2)
        if grace > 0:
            with suppress(subprocess.TimeoutExpired):
                proc.wait(timeout=grace)

        # A child can exit on SIGTERM while descendants keep the pipe open.
        # Kill the group after the grace period so communicate() cannot hang.
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except ProcessLookupError as error:
            _log_cleanup_failure("SIGKILL process-group cleanup", error)
        except OSError:
            proc.kill()
    else:
        _terminate_windows_process(proc, deadline)

    _wait_process(proc, deadline)

def _wait_for_process(proc: subprocess.Popen[bytes], deadline: float | None) -> bool:
    try:
        proc.wait(timeout=_remaining(deadline))
    except subprocess.TimeoutExpired:
        _terminate_process(proc, deadline)
        return True
    return False

def _join_until_deadline(thread: threading.Thread, deadline: float | None) -> bool:
    thread.join(timeout=_remaining(deadline))
    return thread.is_alive()

def _close_stream(stream: IO[bytes] | None) -> None:
    if stream is not None:
        with suppress(OSError, ValueError):
            stream.close()

def _cleanup_failed_process(proc: subprocess.Popen[bytes] | None) -> None:
    if proc is None:
        return
    if os.name == "nt":
        _close_windows_job(proc)
    _close_process_pipes(proc)

def _process_handle(proc):
    process_handle = getattr(proc, "_handle", None)
    if process_handle is None:
        process_handle = getattr(proc, "handle", None)
    return process_handle

def _thread_handle(proc):
    thread_handle = getattr(proc, "_thread_handle", None)
    if thread_handle is None:
        thread_handle = getattr(proc, "_thread", None)
    return thread_handle

def _invalid_windows_handle(handle) -> bool:
    value = handle.value if isinstance(handle, ctypes.c_void_p) else handle
    return value in (None, 0, ctypes.c_void_p(-1).value)

def _first_meaningful_line(text: str) -> str:
    for line in text.splitlines():
        stripped = line.strip()
        if stripped:
            return stripped[:200]
    return ""

def _blank_cpp_region(chars: list[str], start: int, end: int) -> None:
    for index in range(start, end):
        if chars[index] not in "\r\n":
            chars[index] = " "

def _cpp_line_comment_end(text: str, start: int) -> int:
    index = start + 2
    while index < len(text):
        if text[index] == "\n" and (index == start or text[index - 1] != "\\"):
            return index
        index += 1
    return len(text)

def _cpp_quoted_end(text: str, start: int) -> int:
    quote = text[start]
    index = start + 1
    while index < len(text):
        if text[index] == "\\":
            index += 2
            continue
        if text[index] == quote:
            return index + 1
        if text[index] in "\r\n":
            return index + 1
        index += 1
    return len(text)

def _mask_cpp_literals(text: str) -> str:
    """Blank comments and quoted C++ literals while preserving source lines."""

    chars = list(text)
    index = 0
    while index < len(text):
        raw_start = _CPP_RAW_START_RE.match(text, index)
        if raw_start:
            closing = ")" + raw_start.group("delimiter") + '"'
            closing_index = text.find(closing, raw_start.end())
            end = len(text) if closing_index < 0 else closing_index + len(closing)
            _blank_cpp_region(chars, index, end)
            index = end
            continue
        if text.startswith("//", index):
            end = _cpp_line_comment_end(text, index)
            _blank_cpp_region(chars, index, end)
            index = end
            continue
        if text.startswith("/*", index):
            closing_index = text.find("*/", index + 2)
            end = len(text) if closing_index < 0 else closing_index + 2
            _blank_cpp_region(chars, index, end)
            index = end
            continue
        if text[index] in "\"'":
            end = _cpp_quoted_end(text, index)
            _blank_cpp_region(chars, index, end)
            index = end
            continue
        index += 1
    return "".join(chars)

def _load_coverage_json(json_path: Path) -> dict | None:
    try:
        data = json.loads(json_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    return data if isinstance(data, dict) else None

def _parse_coverage_counts(values: object) -> dict[str, int] | None:
    if not isinstance(values, dict):
        return None
    parsed: dict[str, int] = {}
    for key in _COVERAGE_KEYS:
        value = values.get(key)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            return None
        parsed[key] = value
    if parsed["covered_lines"] > parsed["num_statements"]:
        return None
    if parsed["missing_lines"] > parsed["num_statements"]:
        return None
    if parsed["covered_lines"] + parsed["missing_lines"] != parsed["num_statements"]:
        return None
    if parsed["covered_branches"] > parsed["num_branches"]:
        return None
    return parsed

def _parse_line_numbers(value: object, expected: int) -> list[int] | None:
    if not isinstance(value, list) or len(value) != expected:
        return None
    parsed: list[int] = []
    for item in value:
        if isinstance(item, bool) or not isinstance(item, int) or item <= 0:
            return None
        parsed.append(item)
    if len(set(parsed)) != len(parsed):
        return None
    return parsed

def _parse_coverage_file(
    fname: object, finfo: object, project_root: Path
) -> tuple[str, dict] | None:
    if not isinstance(fname, str) or not isinstance(finfo, dict):
        return None
    executed_lines = finfo.get("executed_lines")
    missing_lines = finfo.get("missing_lines")
    summary = finfo.get("summary")
    if (
        not isinstance(executed_lines, list)
        or not isinstance(missing_lines, list)
        or not isinstance(summary, dict)
    ):
        return None
    parsed_summary = _parse_coverage_counts(summary)
    if parsed_summary is None:
        return None
    parsed_executed = _parse_line_numbers(executed_lines, parsed_summary["covered_lines"])
    parsed_missing = _parse_line_numbers(missing_lines, parsed_summary["missing_lines"])
    if parsed_executed is None or parsed_missing is None:
        return None
    if set(parsed_executed).intersection(parsed_missing):
        return None
    return _relative_coverage_path(fname, project_root), {
        "executed_lines": parsed_executed,
        "missing_lines": parsed_missing,
        "summary": parsed_summary,
    }

def _parse_coverage_files(files: object, project_root: Path) -> dict[str, dict] | None:
    if not isinstance(files, dict) or not files:
        return None
    parsed_files: dict[str, dict] = {}
    for fname, finfo in files.items():
        parsed_file = _parse_coverage_file(fname, finfo, project_root)
        if parsed_file is None:
            return None
        relative, file_data = parsed_file
        if relative in parsed_files:
            return None
        parsed_files[relative] = file_data
    return parsed_files

def _sum_coverage_counts(file_data: dict[str, dict]) -> dict[str, int]:
    totals = {key: 0 for key in _COVERAGE_KEYS}
    for finfo in file_data.values():
        summary = finfo["summary"]
        for key in _COVERAGE_KEYS:
            totals[key] += summary[key]
    return totals

def _build_coverage_result(file_data: dict[str, dict], totals: dict[str, int]) -> dict:
    line_cov = _coverage_percent(totals["covered_lines"], totals["num_statements"])
    branch_cov = _coverage_percent(totals["covered_branches"], totals["num_branches"])
    return {
        "files": file_data,
        "branch_cov": branch_cov,
        "line_cov": line_cov,
        "totals": {
            "stmts": totals["num_statements"],
            "miss": totals["missing_lines"],
            "cover": line_cov,
            "branch_cover": branch_cov,
        },
    }

def _coverage_paths_match(
    file_data: dict[str, dict], expected_files: set[str] | None, project_root: Path
) -> bool:
    if expected_files is None:
        return True
    expected = {_relative_coverage_path(path, project_root) for path in expected_files}
    return set(file_data) == expected

def _gcov_source_path(gcov_file: Path, source_files: set[str], project_root: Path) -> str | None:
    candidate = gcov_file.name[:-5].replace("#", "/")
    if candidate in source_files:
        return candidate
    try:
        path = Path(candidate)
        absolute = path if path.is_absolute() else project_root / path
        relative = str(absolute.resolve().relative_to(project_root))
    except ValueError:
        return None
    return relative if relative in source_files else None

def _python_module_name(py_file: Path, source_dirs: list[Path]) -> str | None:
    """Map a .py file to its dotted module name relative to its source dir."""
    for src_dir in source_dirs:
        try:
            rel = py_file.relative_to(src_dir)
        except ValueError:
            continue
        parts = list(rel.with_suffix("").parts)
        if parts and parts[-1] == "__init__":
            parts = parts[:-1]
        # Use only the last N parts as the module name (relative to src_dir root)
        return ".".join(parts) if parts else None
    return None

def _build_python_graph(
    project_root: Path,
) -> tuple[dict[str, set[str]], dict[str, Path]]:
    """Build module -> imported-module graph for in-project Python sources."""
    from ici.core.project import get_source_dirs

    source_dirs = get_source_dirs(project_root)
    all_sources = get_all_python_sources(project_root)

    file_to_module: dict[Path, str] = {}
    module_to_file: dict[str, Path] = {}
    for py_file in all_sources:
        mod_name = _python_module_name(py_file, source_dirs)
        if mod_name:
            file_to_module[py_file] = mod_name
            module_to_file[mod_name] = py_file

    graph: dict[str, set[str]] = {mod: set() for mod in module_to_file}
    for py_file in all_sources:
        importer = file_to_module.get(py_file)
        if not importer:
            continue
        try:
            tree = ast.parse(py_file.read_text(encoding="utf-8", errors="ignore"))
        except (OSError, SyntaxError):
            continue
        for node in ast.walk(tree):
            targets = []
            if isinstance(node, ast.Import):
                targets = [alias.name for alias in node.names]
            elif isinstance(node, ast.ImportFrom) and node.module:
                targets = [node.module]
            for target_mod in targets:
                # Try exact match, then suffix match (e.g., "b" matches "pkg.b").
                # The suffix fallback exists for flat/relative-style imports, but
                # must never claim a stdlib name (e.g. "html", "json") as a match
                # for an in-project module that merely shares its last segment.
                if target_mod in module_to_file:
                    graph[importer].add(target_mod)
                elif target_mod.split(".")[0] not in sys.stdlib_module_names:
                    for known_mod in module_to_file:
                        if known_mod.endswith("." + target_mod) or known_mod == target_mod:
                            graph[importer].add(known_mod)
    return graph, module_to_file

def _iter_cpp_and_headers(project_root: Path) -> list[Path]:
    """Collect all C++ source + header files inside the project boundary."""
    import os

    skip = {".venv", "venv", "build", ".git"}
    suffixes = {".cpp", ".cc", ".cxx", ".c", ".h", ".hpp", ".hh"}
    results = []
    for current, dir_names, file_names in os.walk(project_root):
        dir_names[:] = [d for d in dir_names if d not in skip]
        current_path = Path(current)
        for name in sorted(file_names):
            path = current_path / name
            if not path.is_symlink() and path.suffix in suffixes:
                results.append(path)
    return results

def _build_cpp_graph(
    project_root: Path,
) -> tuple[dict[Path, set[Path]], dict[Path, Path]]:
    """Build file -> included-file graph including headers.

    ``#include "..."`` is resolved by basename only (no ``-I`` search-path
    model here), so a basename shared by more than one file in the project is
    genuinely ambiguous — silently picking the first one found risks wiring a
    false edge to the wrong file. Ambiguous basenames are left unresolved
    instead.
    """
    all_files = _iter_cpp_and_headers(project_root)
    by_name: dict[str, list[Path]] = {}
    for f in all_files:
        by_name.setdefault(f.name, []).append(f)
    unambiguous = {name: paths[0] for name, paths in by_name.items() if len(paths) == 1}

    graph: dict[Path, set[Path]] = {}
    known: dict[Path, Path] = {}
    for f in all_files:
        resolved_f = f.resolve()
        known[resolved_f] = f
        graph[resolved_f] = set()
        try:
            content = f.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        for match in _INCLUDE_RE.finditer(content):
            inc_name = match.group(1)
            target = unambiguous.get(Path(inc_name).name)
            if target and target.resolve() != resolved_f:
                graph[resolved_f].add(target.resolve())
    return graph, known

def _report_link_lines(
    viewer_url: str | None, pages_enabled: bool, remote_path: str, uploaded: bool
) -> list[str]:
    if not uploaded:
        return [
            "> ❌ **HTML 리포트 업로드 실패** — 토큰 권한(`contents: write`)과 "
            "Workflow Run 로그를 확인해 주세요."
        ]
    if viewer_url:
        return [
            f"[![Open Report](https://img.shields.io/badge/{quote('📊_HTML_리포트_열기')}-38bdf8?style=for-the-badge)]({viewer_url})",
            "",
            f"<sub>뷰어 URL: {viewer_url}</sub>",
        ]
    if pages_enabled:
        return [f"📄 리포트가 `{remote_path}`에 게시되었습니다."]
    return [
        f"> 📦 리포트가 `{remote_path}`(gh-pages)에 푸시되었습니다. "
        "**최초 1회** Settings → Pages → Source에서 `gh-pages`를 선택하면 이 댓글에 뷰어 링크가 표시됩니다."
    ]

def _footer_line(mode: str, remote_path: str, run_url: str | None) -> str:
    parts = [f"모드 `{mode}`", f"경로 `{remote_path}`"]
    if run_url:
        parts.append(f"[⚙️ Workflow Run]({run_url})")
    parts.append("<sub>generated by ici</sub>")
    return "<br/>".join(parts)

def _check_file_for_leaks(rel_path: str, content: str) -> list[InspectionTarget]:
    try:
        tree = ast.parse(content, filename=rel_path)
    except SyntaxError:
